from (values
  ('standing', 'breakfall', '낙법', 'Breakfall', array['뒤낙법','옆낙법','우케미','브레이크폴']::text[], array['턱을 당겨 뒤통수가 바닥에 닿지 않게 한다','엉덩이 → 등 순서로 둥글게 닿으며 넘어진다','닿는 순간 팔을 45도로 펴서 손바닥으로 바닥을 친다(옆낙법은 한 팔)','무릎을 굽혀 세우고 바로 일어날 수 있게 자세를 모은다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: 일반 기초', 1),
  ('standing', 'grip-fighting', '그립 파이팅 (기본 그립)', 'Grip Fighting (Collar & Sleeve)', array['그립 싸움','깃 소매 잡기','그립파이팅','칼라 슬리브 그립']::text[], array['한 손은 상대 깃(칼라), 반대 손은 같은 쪽 소매 끝을 잡는다','상대가 내 깃을 잡으면 손목을 돌리고 팔을 당겨 바로 떼어낸다','내 그립은 팔꿈치를 몸에 붙여 짧게 유지한다','그립을 먼저 잡은 쪽이 테이크다운이나 가드 풀링을 시작한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing', 2),
  ('standing', 'pulling-guard', '가드 풀링', 'Pulling Guard', array['풀 가드','가드 당기기','가드 풀','풀링 가드']::text[], array['깃과 소매(또는 손목)를 잡는다','한 발을 상대 골반에 밟고 엉덩이를 뒤로 떨어뜨리며 상대를 당긴다','밟은 발 반대 다리를 상대 허리에 감는다','양 다리를 상대 등 뒤에서 걸어 클로즈드 가드를 완성한다(또는 바로 오픈 가드)']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-guard/bottom 1위', 3),
  ('standing', 'double-leg-takedown', '더블 레그 테이크다운', 'Double Leg Takedown', array['더블렉','더블 레그','더블렉 테이크다운','양다리 잡기']::text[], array['자세를 낮추고 앞발을 상대 다리 사이로 깊게 내딛는다','양팔로 상대 무릎 뒤를 감아 당긴다','머리를 상대 옆구리에 붙이고 가슴을 앞으로 민다','뒷발을 끌어와 옆으로 돌며 눕히고 바로 사이드로 올라간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: 일반', 4),
  ('standing', 'single-leg-takedown', '싱글 레그 테이크다운', 'Single Leg Takedown', array['싱글렉','싱글 레그','싱글렉 테이크다운','한다리 잡기']::text[], array['앞발을 내딛으며 상대 한쪽 다리를 양팔로 안는다','머리를 상대 가슴 안쪽에 붙여 길로틴을 막는다','잡은 다리를 내 허벅지 사이에 끼우고 일어선다','다리를 바깥으로 밀거나 걸어 넘어뜨리고 패스 자세를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: 일반', 5),
