  ('standing', 'firemans-carry', '파이어맨 캐리', 'Fireman''s Carry', array['어깨 메치기(레슬링)','파이어맨즈 캐리','카타구루마','어깨로메치기']::text[], array['상대 한 팔(소매)을 잡아 당기며 상대 다리 사이로 무릎을 꿇고 들어간다','반대 팔을 상대 다리 사이로 넣어 잡은 팔과 같은 쪽 허벅지를 안아 상대를 어깨에 걸친다','등으로 상대를 들어 잡은 팔 쪽으로 넘긴다','넘어진 상대 위로 사이드 컨트롤']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph clinch/top (기 시도 6)', 25),
  ('standing', 'uchi-mata', '허벅다리걸기', 'Uchi Mata', array['우치마타']::text[], array['깃과 소매를 잡고 상대를 앞으로 당긴다','소매 쪽으로 돌아 들어가며 허리를 붙인다','안쪽 다리를 상대 허벅지 안쪽으로 높게 들어 올린다','상체를 숙이며 다리를 들어 넘긴다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph clinch/top (기 시도 10)', 26),
  ('standing', 'harai-goshi', '허리후리기', 'Harai Goshi', array['하라이고시']::text[], array['깃과 소매를 잡고 상대를 앞으로 당긴다','돌아 들어가며 엉덩이를 상대 앞에 붙인다','다리를 상대 허벅지 바깥쪽으로 쓸어 올린다','상체를 숙이며 넘긴다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 6)', 27),
  ('standing', 'tai-otoshi', '몸떨어뜨리기', 'Tai Otoshi', array['타이오토시','빗당겨치기','체락']::text[], array['깃과 소매를 잡고 상대를 앞으로 당긴다','돌아 들어가며 한 다리를 상대 발 앞에 뻗어 가로막는다','엉덩이를 붙이지 않고 그립으로 상대를 다리 위로 당겨 넘긴다','넘어가면 소매를 놓지 않고 사이드로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 2)', 28),
  ('standing', 'ippon-seoi-nage', '한팔업어치기', 'Ippon Seoi Nage', array['입폰 세오이나게']::text[], array['한쪽 소매를 잡고 상대를 당긴다','돌아 들어가며 반대 팔을 상대 겨드랑이 아래로 넣어 팔을 감는다','무릎을 굽혀 엉덩이를 낮게 붙인다','다리를 펴며 숙여 어깨 너머로 넘긴다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 3)', 29),
  ('standing', 'morote-seoi-nage', '양손업어치기', 'Morote Seoi Nage', array['모로테 세오이나게']::text[], array['깃과 소매를 잡는다','돌아 들어가며 깃 잡은 팔꿈치를 상대 겨드랑이에 넣는다','엉덩이를 낮게 붙인다','다리를 펴며 숙여 넘긴다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 2)', 30),
  ('standing', 'kouchi-gari', '안뒤축후리기', 'Kouchi Gari', array['코우치가리','안발목 후리기','코우치','안뒤축']::text[], array['상대를 뒤로 밀어 한 발 뒤꿈치에 체중을 싣게 한다','발바닥으로 상대 같은 쪽 발뒤꿈치 안쪽을 쓸어 낸다','상체는 뒤로 밀어 균형을 깬다','넘어가면 다리 사이로 들어가 패스']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph clinch/top (기 시도 9)', 31),
