  ('standing', 'kosoto-gake', '밭뒤축걸기', 'Kosoto Gake', array['코소토가케','바깥 걸기']::text[], array['상대를 뒤로 밀어 체중을 뒤에 싣는다','다리로 상대 다리 바깥에서 종아리를 걸어 감는다','건 채 상체를 밀며 체중으로 넘긴다','넘어가면 사이드나 하프 탑']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 9)', 33),
  ('standing', 'deashi-harai', '나오는발차기', 'Deashi Harai', array['데아시하라이','앞발 쓸기']::text[], array['상대가 발을 옮기는 순간을 본다','옮기는 발이 바닥에 닿기 직전 발바닥으로 발목을 쓸어 낸다','그립으로 상대 상체를 반대로 당긴다','넘어가면 사이드로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 1)', 34),
