  ('standing', 'tani-otoshi', '모두걸기', 'Tani Otoshi', array['타니오토시','골짜기 떨어뜨리기']::text[], array['상대 옆이나 뒤로 돌아 한 다리를 상대 양 다리 뒤로 길게 뻗는다','상대 허리나 깃을 잡고 뒤로 앉으며 당긴다','상대가 내 다리에 걸려 뒤로 넘어진다','바로 사이드나 하프 탑으로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 8)', 36),
  ('standing', 'sumi-gaeshi', '안오금띄기', 'Sumi Gaeshi', array['스미가에시','모서리 뒤집기']::text[], array['깃이나 언더훅을 잡고 상대를 앞으로 당긴다','뒤로 앉으며 한 발을 상대 허벅지 안쪽에 넣는다(버터플라이 훅)','당기며 훅으로 들어 올려 머리 위로 넘긴다','굴러 올라와 마운트나 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph standing-position/top (기 시도 1)', 37),
