  ('spider-lasso', 'triangle-from-collar-sleeve', '트라이앵글 (칼라 슬리브)', 'Triangle from Collar Sleeve Guard', array['칼라 슬리브 트라이앵글','깃 소매 트라이앵글','칼라슬리브 삼각']::text[], array['깃과 소매를 잡고 소매 쪽 발을 이두에, 반대 발을 골반에 댄다','깃을 당겨 상대 자세를 무너뜨리면서 소매 잡은 팔을 바깥 아래로 밀어 낸다','이두를 밀던 발을 떼어 그 다리를 상대 목 뒤로 넘긴다','골반에 댔던 다리로 그 발목을 걸어 삼각형을 만든다','깃을 놓고 상대 머리를 당기며 무릎을 조여 조른다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 33),
  ('spider-lasso', 'omoplata-from-collar-sleeve', '오모플라타 (칼라 슬리브)', 'Omoplata from Collar Sleeve Guard', array['칼라 슬리브 오모플라타','깃 소매 오모플라타','칼라슬리브 오모']::text[], array['깃과 소매를 잡고 소매 쪽 발을 이두에, 반대 발을 골반에 댄다','소매를 당기면서 이두를 밀던 발을 상대 팔 바깥으로 돌려 그 팔이 내 다리 아래에 오게 한다','골반 발로 밀며 엉덩이를 빼고 그 다리를 상대 어깨 위로 넘겨 다리를 모은다','소매를 놓지 않고 앉아 올라오며 상대 팔을 등 뒤로 꺾는다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 34),
  ('spider-lasso', 'triangle-from-lasso', '트라이앵글 (라쏘)', 'Triangle from Lasso Guard', array['라쏘 트라이앵글','라소 트라이앵글','라쏘 삼각']::text[], array['라쏘를 깊게 걸고 반대 손으로 상대 반대쪽 소매나 깃을 잡아 그 팔을 내 쪽으로 당긴다','반대 발로 골반을 밀어 상대 자세를 무너뜨린다','라쏘 다리를 위로 펴서 겨드랑이에서 발을 빼며 그 다리를 상대 목 뒤로 넘긴다(라쏘 걸었던 팔은 다리 아래 바깥에 남는다)','반대 다리로 발목을 걸어 삼각형을 만들고 머리를 당겨 조른다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 35),
  ('lapel-guard', 'lapel-guard-basics', '라펠 가드 (기본)', 'Lapel Guard (Basics)', array['라펠','라펠가드','옷깃 가드','깃 가드']::text[], array['상대 도복 앞자락 끝(라펠)을 허리띠 아래에서 빼내 손에 잡는다','라펠을 상대 다리 뒤(오금)로 돌려 바깥으로 꺼낸다','꺼낸 라펠 끝을 당겨 상대 다리와 자세를 묶는다','발은 상대 골반이나 무릎에 대고 거리를 지킨다','데라히바 · 라쏘 · 웜 가드 스윕으로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 1),
  ('lapel-guard', 'worm-guard-entry', '웜 가드 진입', 'Worm Guard Entry', array['웜가드','웜 가드','벌레 가드']::text[], array['상대 라펠 끝을 빼서 상대 한쪽 다리 뒤(오금)로 돌려 바깥으로 꺼낸다','꺼낸 라펠을 내 같은 쪽 정강이 위로 넘겨 그 다리로 라펠을 감는다','라펠 끝은 반대 손으로 잡고 감은 발은 상대 골반에 둔다','라펠을 당겨 상대 상체를 앞으로 숙이게 하며 스윕을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 18)', 2),
  ('lapel-guard', 'lapel-sweep-to-back', '라펠 스윕 → 백', 'Lapel Sweep to Back', array['라펠 백 테이크','웜 가드 백']::text[], array['라펠로 상대 다리를 묶은 채 반대 손으로 허리띠나 바지를 잡는다','라펠을 가슴 쪽으로 당겨 상대 상체를 앞으로 숙이게 한다','상대가 손을 짚으면 묶인 다리 바깥쪽으로 돌아 나간다','허리띠를 당겨 상대를 앉히고 등 뒤로 올라가 훅을 넣는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 17)', 3),
  ('lapel-guard', 'lapel-elevator-sweep', '라펠 엘리베이터 스윕', 'Lapel Elevator Sweep', array['라펠 엘리베이터']::text[], array['라펠로 상대 다리를 묶은 채 반대 발을 상대 허벅지 안쪽에 훅으로 넣는다','라펠을 가슴 쪽으로 당겨 상대 자세를 숙이게 한다','훅으로 상대 다리를 들어 올리며 묶인 다리 쪽으로 넘긴다','라펠을 놓지 않고 따라 올라가 마운트나 사이드로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 12)', 4),
  ('lapel-guard', 'lapel-to-de-la-riva', '라펠 → 데라히바', 'Lapel to De La Riva', array['라펠 DLR','라펠 데라히바']::text[], array['라펠 잡은 손 반대쪽 발을 상대 다리 바깥에서 감아 데라히바 훅을 건다','발목 대신 라펠을 당겨 상대 자세를 묶는다','반대 발은 상대 골반이나 무릎을 밀어 거리를 지킨다','데라히바 스윕이나 백 테이크로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 10)', 5),
  ('lapel-guard', 'lapel-to-lasso', '라펠 → 라쏘', 'Lapel to Lasso Guard', array['라펠 라쏘','라펠 라소']::text[], array['라펠을 당겨 상대가 상체를 숙이면 반대 손으로 소매를 잡는다','소매 잡은 쪽 발을 그 팔 바깥에서 안으로 감아 라쏘를 건다','라펠과 라쏘를 함께 당겨 상대 상체와 팔을 묶는다','라쏘 스윕이나 오모플라타로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 6),
  ('lapel-guard', 'lapel-to-spider', '라펠 → 스파이더', 'Lapel to Spider Guard', array['라펠 스파이더']::text[], array['라펠 반대 손으로 상대 소매를 잡는다','소매 잡은 쪽 발을 상대 이두에 올린다','라펠을 당기며 이두를 밀어 상대 팔을 편다','스파이더 스윕이나 트라이앵글로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 7),
  ('lapel-guard', 'lapel-omoplata-entry', '오모플라타 (라펠)', 'Lapel Omoplata Entry', array['라펠 오모플라타']::text[], array['라펠로 상대 한 팔을 몸에 묶어 팔이 아래로 처지게 한다','엉덩이를 바깥으로 빼며 그쪽 다리를 상대 팔 위로 넘겨 등 뒤에 건다','두 발을 모아 상대 어깨를 잠그고 반대 손으로 허리띠를 잡아 구르지 못하게 한다','앉아 올라오며 상체를 앞으로 눌러 어깨를 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 8)', 8),
  ('lapel-guard', 'lapel-triangle-setup', '트라이앵글 (라펠)', 'Lapel Triangle Setup', array['라펠 트라이앵글']::text[], array['라펠로 상대 한 팔을 묶어 내 다리 바깥에 둔다','묶인 팔 쪽 어깨 위로 그쪽 다리를 넘겨 상대 목 뒤에 건다','상대 머리를 당겨 내리며 반대 다리 오금으로 발목을 걸어 잠근다','안에 남은 팔을 반대쪽으로 넘기고 무릎을 모으며 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/bottom (기 시도 5)', 9),
  ('lapel-guard', 'lapel-clear-to-toreando', '라펠 풀고 토레안도', 'Lapel Clear to Toreando Pass', array['라펠 패스']::text[], array['상대가 잡은 라펠 쪽 깃을 몸 쪽으로 당겨 느슨하게 한다','라펠을 내 다리와 몸에서 완전히 빼낸다','라펠을 빼자마자 상대 양 무릎을 잡아 옆으로 밀어 토레안도','무릎을 바닥에 눌러 두고 돌아 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('lapel-guard', 'knee-slice-despite-lapel', '니슬라이스 (라펠 잡힌 채)', 'Knee Slice Despite Lapel', array['라펠 니슬라이스']::text[], array['라펠이 다리에 감겨도 무릎을 상대 허벅지 위로 올린다','깃을 잡아 상체를 눌러 둔다','정강이로 미끄러져 라펠을 풀어낸다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/top (기 시도 14)', 11),
  ('lapel-guard', 'distance-creation-to-reset', '거리 만들어 리셋 (라펠 상대)', 'Distance Creation to Reset', array['라펠 리셋']::text[], array['라펠을 잡히면 뒤로 물러서며 다리를 편다','라펠을 당겨 느슨하게 하고 몸에서 빼낸다','상대가 따라오면 그립을 다시 잡는다','오픈 가드 패스부터 다시']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/top (기 시도 12)', 12),
  ('lapel-guard', 'leg-drag-while-clearing-lapel', '레그 드래그 (라펠 풀며)', 'Leg Drag While Clearing Lapel', array['라펠 레그 드래그']::text[], array['라펠 감긴 다리를 손으로 잡는다','라펠을 풀며 그 다리를 반대 엉덩이로 끌어온다','무릎을 상대 엉덩이에 붙인다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph lapel-guard/top (기 시도 11)', 13),
  ('lapel-guard', 'stack-pass-over-lapel', '스택 패스 (라펠 상대)', 'Stack Pass Over Lapel Barrier', array['라펠 스택']::text[], array['라펠 감긴 다리를 어깨로 든다','양팔을 다리 아래로 넣어 깍지','엉덩이를 들어 스택','돌아 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 14),
  ('lapel-guard', 'worm-guard-sweep', '웜 가드 스윕', 'Worm Guard Sweep', array['웜가드 스윕','웜 가드 넘기기']::text[], array['웜 가드에서 라펠을 가슴 쪽으로 당겨 상대 상체를 숙이게 한다','라펠 감은 발로 상대 골반을 밀며 반대 손으로 상대 발목이나 바지를 잡는다','라펠을 당기며 상대 다리를 들어 묶인 다리 쪽으로 넘긴다','라펠을 놓지 않고 따라 올라가 사이드나 마운트로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 15),
  ('lapel-guard', 'defend-worm-guard-posture', '웜 가드 상대 자세 지키기', 'Posture Defense vs Worm Guard', array['라펠 가드 방어','웜가드 디펜스']::text[], array['상대가 라펠을 빼려 하면 라펠 쪽 손으로 먼저 잡아 감지 못하게 막는다','이미 감겼으면 엉덩이를 뒤로 빼고 등을 세워 숙여지지 않게 한다','감긴 다리 무릎을 상대 쪽으로 세우고 체중을 앞발이 아닌 뒷발에 둔다','라펠을 몸 쪽으로 당겨 느슨해지면 다리를 빼내 패스로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 16),
  ('x-guard', 'x-guard', 'X 가드', 'X-Guard', array['엑스 가드','X가드','엑스가드']::text[], array['상대가 서면 한쪽 다리 아래로 들어가 그 다리를 어깨에 얹고 팔로 안는다','아래쪽 다리는 상대 반대 다리 무릎 뒤(오금)에 훅으로 건다','위쪽 다리 발은 상대 반대 허벅지 안쪽이나 골반에 대 두 다리가 X 모양이 되게 한다','안은 발목을 가슴으로 당기며 두 훅으로 밀어 상대 다리를 벌린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 1),
  ('x-guard', 'x-guard-sweep', 'X 가드 스윕', 'X-Guard Sweep', array['X가드 넘기기','X가드 스윕']::text[], array['안은 다리를 가슴 쪽으로 당기고 두 훅으로 상대 반대 다리를 밀어 다리를 벌린다','상대가 뒤로 앉거나 손을 짚으면 안은 발목을 놓지 않는다','상대 다리를 든 채 일어나 밀어 눕힌다','다리를 놓지 않고 패스 자세로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 24)', 2),
  ('x-guard', 'tomahawk-sweep', '토마호크 스윕', 'Tomahawk Sweep', array['X가드 토마호크']::text[], array['X 가드에서 두 훅으로 상대 반대 다리를 든다','어깨에 얹은 다리를 내려 그 발목을 손으로 잡는다','발목을 당겨 상대가 손을 짚지 못하게 하며 들린 다리를 도끼질하듯 바깥으로 넘긴다','상대가 등으로 넘어지면 다리를 넘어 마운트로 올라온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 8)', 3),
  ('x-guard', 'x-guard-technical-stand-up', 'X 가드 → 일어나기', 'X-Guard Technical Stand Up', array['X가드 스탠드업']::text[], array['상대 다리를 안은 채 한 손으로 바닥을 짚는다','엉덩이를 들고 안쪽 다리를 빼서 일어난다','상대 다리를 든 채 서서 밀어 눕힌다','패스 자세']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph x-guard/bottom (기 시도 10)', 4),
