  ('x-guard', 'knee-extraction', '무릎 빼기 (앵클락 상대)', 'Knee Extraction from Ankle Lock', array['무릎 빼서 서기']::text[], array['잡힌 다리 무릎을 상대 다리 사이에서 빼며 일어선다','상대 훅을 손으로 눌러 떼어낸다','뒤로 물러선다','스탠딩']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph straight-ankle-lock-control/top (기 시도 16)', 17),
  ('x-guard', 'standing-escape-from-slx', '싱글 레그 X 빠져나오기 (서서)', 'Standing Escape from SLX', array['SLX 이스케이프']::text[], array['잡힌 발의 무릎을 바깥으로 돌리지 않게 안쪽으로 유지한다','상대 골반 발을 손으로 눌러 떼어낸다','다리를 빼며 뒤로 물러난다','다시 패스 자세']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/top (기 시도 29)', 18),
  ('x-guard', 'backstep-from-single-leg-x', '백스텝 (싱글 레그 X 상대)', 'Backstep from Single Leg X', array['SLX 백스텝']::text[], array['잡힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 손으로 눌러 둔다','상대 옆으로 돌아 들어간다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph single-leg-x-guard/top (기 시도 21)', 19),
  ('x-guard', 'reverse-x-guard', '리버스 X 가드', 'Reverse X-Guard', array['리버스 엑스']::text[], array['상대 다리 아래로 들어가 한 다리를 어깨에 얹되 몸은 반대로 향한다','안쪽 다리로 상대 반대 무릎 뒤를 건다','바깥 다리는 허벅지를 민다','발목을 당겨 균형을 뺏는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('x-guard', 'reverse-x-guard-sweep', '리버스 X 가드 스윕', 'Reverse X-Guard Sweep', array['리버스 X 스윕']::text[], array['얹은 다리를 안고 훅으로 상대 다리를 든다','상대 체중이 뜨면 옆으로 넘긴다','굴러 올라온다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 28)', 21),
  ('x-guard', 'elevation-sweep-to-mount', '엘리베이션 스윕 (리버스 X)', 'Elevation Sweep to Mount', array['들어 올려 넘기기']::text[], array['양 다리로 상대 다리를 들어 올린다','상대가 손을 짚으면 그쪽 발목을 당긴다','등으로 넘긴다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 14)', 22),
  ('x-guard', 'reverse-x-to-back-take', '리버스 X → 백 테이크', 'Reverse X to Back Take', array['리버스 X 백']::text[], array['얹은 다리를 안고 상대 뒤로 돈다','허리띠를 잡고 상대를 앉힌다','등 뒤로 나와 훅','백']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph reverse-x-guard/bottom (기 시도 11)', 23),
  ('x-guard', 'backstep-pass-from-reverse-x', '백스텝 패스 (리버스 X 상대)', 'Backstep Pass from Reverse X-Guard', array['리버스 X 백스텝']::text[], array['얹힌 다리를 뒤로 돌리며 몸을 돌린다','상대 다리를 눌러 둔다','옆으로 돌아 들어간다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 24),
  ('x-guard', 'x-guard-back-take', 'X 가드 → 백 테이크', 'X-Guard to Back Take', array['X가드 백','엑스 가드 백 잡기']::text[], array['X 가드에서 두 훅으로 상대 반대 다리를 밀어 상대가 몸을 돌리게 한다','상대 등이 보이면 어깨에 얹은 다리를 내리고 허리띠나 허리를 잡는다','상대 무릎 뒤를 당겨 앉히며 등 뒤로 올라온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤을 완성한다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 25),
  ('half-guard', 'half-guard-basics', '하프가드 (자세 · 프레임)', 'Half Guard (Basics & Frames)', array['하프','반 가드']::text[], array['상대 한쪽 다리를 내 양 다리로 감아 발목을 잠근다','감은 다리 쪽으로 옆으로 돌아 눕는다 — 등이 바닥에 평평하면 진다','위쪽 팔뚝은 상대 목, 아래 팔뚝은 골반에 대어 프레임을 만든다(손바닥이 아니라 뼈로)','밀기 전에 먼저 브릿지로 상대 체중을 띄운 뒤 엉덩이를 빼서 공간을 만든다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.1~3.2', 1),
  ('half-guard', 'knee-shield-half-guard', '니 쉴드 하프가드', 'Knee Shield Half Guard', array['제트 가드','Z 가드','Z가드','니실드','니쉴드']::text[], array['하프가드에서 위쪽 무릎을 상대 배나 골반 앞에 가로로 세운다(낮은 니 쉴드)','아래 다리는 상대 다리를 계속 감아 둔다','같은 쪽 손은 내 무릎, 반대 손은 상대 이두를 잡아 거리를 지킨다','상대가 무릎을 밀어 치우면 그 팔을 따라 들어가 언더훅으로 바꾼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.3 · BJJGraph half-guard/bottom 1위', 2),
  ('half-guard', 'half-guard-underhook', '하프가드 언더훅 잡기', 'Winning the Underhook from Half Guard', array['언더훅 싸움','언더훅']::text[], array['팔로 먼저 뻗지 말고 무릎을 들어 올려 상대 몸을 위로 밀어 공간을 만든다','생긴 공간으로 팔을 넣어 상대 겨드랑이 아래를 감는다','손은 상대 등 위가 아니라 골반 가까이, 팔꿈치는 몸에 붙여 짧게 잡는다','언더훅을 잡으면 머리를 상대 겨드랑이 밑으로 빼고 스윕이나 백 테이크로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.4 ''다리로 공간을 만들고 팔이 채운다''', 3),
  ('half-guard', 'half-guard-underhook-sweep', '하프가드 언더훅 스윕 (올드 스쿨)', 'Half Guard Underhook Sweep (Old School)', array['언더훅 스윕','올드 스쿨 스윕']::text[], array['하프가드에서 언더훅을 잡고 옆으로 돌아 눕는다','머리를 상대 겨드랑이 아래로 넣어 자세를 낮춘다','언더훅 팔로 상대 다리를 안아 내리고(또는 발목을 잡고) 중심을 뺏는다','앞으로 밀며 올라와 탑으로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph', 4),
  ('half-guard', 'half-guard-back-take', '하프가드 백 테이크', 'Back Take from Half Guard', array['하프에서 백 잡기']::text[], array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎을 세워 상대 등 뒤로 돌아 올라온다(도그파이트)','한 손으로 허리띠나 허리를 잡고 가슴을 상대 등에 붙인다','훅을 넣고 시트벨트를 잡아 백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.5 · BJJGraph 3위', 5),
  ('half-guard', 'half-guard-recovery', '하프가드에서 가드 회복', 'Half Guard to Full Guard Recovery', array['가드 리커버리','풀 가드 복귀']::text[], array['상대 목과 골반에 프레임을 만든다','브릿지 → 엉덩이 빼기(쉬림프)를 한 번이 아니라 두 번 한다','감아 둔 다리 쪽 무릎을 상대 배 앞으로 가져온다','반대 다리를 상대 허리 위로 넘겨 클로즈드 가드나 버터플라이로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.2 ''더블 힙 이스케이프'' · BJJGraph', 6),
  ('half-guard', 'deep-half-guard', '딥 하프가드', 'Deep Half Guard', array['딥 하프']::text[], array['하프가드에서 상대 다리 아래로 깊게 파고들어 허벅지가 내 가슴 위에 오게 한다','감은 다리 쪽 팔로 상대 허벅지를 안고 머리는 상대 다리 아래로 숨긴다','반대 손으로 상대 발목이나 허리띠를 잡아 자세를 고정한다','상대 다리를 들어 올리며 돌아 위로 올라온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom', 7),
  ('half-guard', 'kimura-half-guard', '기무라 (하프가드)', 'Kimura from Half Guard', array['하프 기무라','기무라 트랩']::text[], array['상대가 내 머리를 누르거나 바닥을 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','옆으로 돌아 팔꿈치를 몸에 붙이고 상대 어깨를 바닥 쪽으로 누른다','바로 안 꺾이면 스윕이나 백 테이크로 잇는다(기무라 트랩)']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §3.6 · §11.3', 8),
  ('half-guard', 'half-guard-frames', '하프가드 프레임 · 더블 힙 이스케이프', 'Half Guard Frames & Double Hip Escape', array['하프 프레임','브릿지 앤 프레임']::text[], array['위 팔뚝은 상대 목, 아래 팔뚝은 골반(손바닥 말고 뼈로)','먼저 브릿지로 상대 체중을 띄운다','프레임으로 공간을 지키며 엉덩이를 뺀다(한 번 더)','무릎을 넣거나 언더훅을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('half-guard', 'z-guard', 'Z 가드', 'Z-Guard', array['제트 가드','Z가드','지 가드','높은 니 쉴드','하이 니 쉴드']::text[], array['니 쉴드 무릎을 상대 가슴이나 어깨 높이로 올린다','아래 다리는 상대 다리를 감는다','같은 쪽 팔로 상대 머리를 밀어 프레임','반대 손으로 소매나 깃을 잡고 스윕 · 회복을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('half-guard', 'z-guard-sweep', 'Z 가드 스윕', 'Z-Guard Sweep', array['제트 가드 스윕']::text[], array['깃이나 소매를 잡고 니 쉴드로 상대를 민다','상대가 밀고 들어오면 니 쉴드를 풀어 그 다리로 상대 허벅지를 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 위로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph z-guard/bottom (기 시도 17)', 11),
  ('half-guard', 'z-guard-to-half-guard', 'Z 가드 → 하프가드 (언더훅)', 'Z-Guard to Half Guard', array['니 쉴드 풀어 언더훅']::text[], array['상대가 니 쉴드를 밀어 치우면 그 팔을 따라 들어간다','팔을 상대 겨드랑이 아래로 넣어 언더훅','엉덩이를 상대 쪽으로 당긴다','언더훅 스윕이나 백 테이크']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph z-guard/bottom (기 시도 15)', 12),
  ('half-guard', 'knee-shield-to-closed-guard', '니 쉴드 → 클로즈드 가드', 'Knee Shield to Closed Guard', array['니 쉴드 리가드']::text[], array['니 쉴드로 상대를 밀어 거리를 만들고 엉덩이를 뺀다','감았던 아래 다리를 빼내 상대 허리 위로 넘긴다','니 쉴드 다리도 상대 등 뒤로 넘겨 두 발을 잠근다','클로즈드 가드에서 상대 자세를 무너뜨린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-shield-half-guard/bottom (기 시도 8)', 13),
  ('half-guard', 'kimura-from-knee-shield', '기무라 (니 쉴드)', 'Kimura from Knee Shield Half Guard', array['니 쉴드 기무라']::text[], array['상대가 니 쉴드를 밀려고 짚은 손목을 잡는다','반대 팔로 상대 윗팔을 감아 내 손목을 잡는다(8자 그립)','니 쉴드로 상대를 밀어내며 몸을 옆으로 돌려 어깨를 바닥 쪽으로 누른다','팔을 등 뒤로 돌려 꺾고, 안 꺾이면 스윕으로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 14),
  ('half-guard', 'sweep-from-knee-shield', '니 쉴드 스윕', 'Sweep from Knee Shield', array['니 쉴드 넘기기']::text[], array['깃과 소매를 잡는다','니 쉴드 다리를 풀어 상대 허벅지 안쪽을 든다','아래 다리로 상대 발목을 걸어 당긴다','넘기고 마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-shield-half-guard/bottom (기 시도 4)', 15),
  ('half-guard', 'old-school-sweep', '올드 스쿨 스윕', 'Old School Sweep', array['올드스쿨']::text[], array['언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로','언더훅 팔로 상대 먼 쪽 발목을 잡는다','발목을 당기며 앞으로 밀고 올라온다','사이드 탑']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph old-school/bottom (기 시도 24)', 16),
  ('half-guard', 'defend-old-school-sweep', '올드 스쿨 스윕 방어', 'Defend Old School Sweep', array['올드스쿨 디펜스']::text[], array['상대가 언더훅 잡으면 바로 위저(오버훅)로 팔을 감는다','잡힌 발목 쪽 다리를 뒤로 빼 펴며 엉덩이를 낮춘다','크로스페이스로 상대 머리를 눌러 둔다','다시 하프 탑']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph old-school/top (기 시도 16)', 17),
  ('half-guard', 'dogfight-position', '도그파이트', 'Dogfight Position', array['도그 파이트']::text[], array['언더훅을 잡고 무릎으로 일어나 상대 다리를 안는다','상대도 위저로 버티면 둘 다 네발 자세(도그파이트)','머리를 상대 옆구리에 붙인다','상대 반응에 따라 스윕 · 백 테이크 · 재하프']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph leg-weave/bottom (기 시도 14)', 18),
  ('half-guard', 'dogfight-sweep', '도그파이트 스윕', 'Dogfight Sweep', array['도그파이트에서 넘기기']::text[], array['상대가 몸을 바깥으로 돌리면 먼 쪽 발목을 잡아 당긴다','상대가 내 쪽으로 돌면 무릎을 밀어 엉덩이를 바닥으로','어깨와 머리로 밀어붙인다','위로 올라와 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 28)', 19),
  ('half-guard', 'forward-drive-sweep-from-dogfight', '도그파이트 전진 스윕', 'Forward Drive Sweep from Dogfight', array['밀어 넘기기']::text[], array['상대 다리를 안은 채 어깨를 상대 골반에 붙인다','발로 바닥을 밀며 앞으로 돌진한다','상대가 뒤로 넘어진다','마운트나 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 13)', 20),
  ('half-guard', 're-pull-half-guard-from-dogfight', '도그파이트 → 하프가드 복귀', 'Re-pull Half Guard from Dogfight', array['하프 다시 잡기']::text[], array['스윕이 막히면 상대 다리를 안은 채 엉덩이를 바닥에 앉힌다','안은 다리를 내 양 다리로 감는다','옆으로 돌아 눕는다','언더훅 하프가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/bottom (기 시도 16)', 21),
  ('half-guard', 're-flatten-from-dogfight', '도그파이트 상대 다시 눕히기', 'Re-flatten from Dogfight', array['도그파이트 탑 디펜스']::text[], array['위저로 상대 어깨를 눌러 둔다','잡힌 다리를 뒤로 빼며 엉덩이를 낮춘다','크로스페이스로 머리를 눌러 눕힌다','하프 탑']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 38)', 22),
  ('half-guard', 'crossface-from-dogfight', '크로스페이스 (도그파이트 탑)', 'Crossface from Dogfight', array['도그파이트 크로스페이스']::text[], array['위저를 유지한 채 반대 팔로 상대 얼굴을 반대쪽으로 민다','상대 등이 바닥으로 가게 돌린다','다리를 빼며 가슴을 붙인다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 32)', 23),
  ('half-guard', 'snap-down-from-dogfight', '스냅 다운 (도그파이트 탑)', 'Snap Down from Dogfight', array['도그파이트 스냅다운']::text[], array['위저 반대 손으로 상대 목 뒤를 잡는다','위저와 함께 아래로 강하게 낚아챈다','상대 머리가 바닥으로 가면 가슴으로 누른다','프론트 헤드락']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph dogfight-position/top (기 시도 30)', 24),
  ('half-guard', 'flattened-half-guard', '눌린 하프가드에서 회복', 'Flattened Half Guard Recovery', array['플랫 하프','눌렸을 때']::text[], array['상대가 언더훅 · 크로스페이스로 눌렀을 때 손을 상대 팔꿈치에 댄다','브릿지하며 어깨를 띄운다','팔꿈치를 가슴에 붙여 작게 돌려 언더훅을 되찾는다','옆으로 돌아 니 쉴드나 언더훅 하프']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('half-guard', 'deep-half-entry-from-flattened', '눌린 하프 → 딥 하프', 'Deep Half Entry from Flattened', array['눌렸을 때 딥 하프']::text[], array['상대 다리 아래로 머리를 넣는다','엉덩이를 빼며 상대 허벅지 아래로 깊게 들어간다','허벅지를 안는다','딥 하프']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph flattened-half-guard/bottom (기 시도 6)', 26),
  ('half-guard', 'kimura-from-flattened-half-top', '기무라 (하프 탑)', 'Kimura from Half Guard Top', array['하프 탑 기무라']::text[], array['상대가 밀어내는 손목을 잡는다','반대 팔을 팔 아래로 넣어 내 손목','상대 어깨를 바닥에 누르며 몸을 낮춘다','팔을 등 뒤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 27),
  ('half-guard', 'deep-half-sweep', '딥 하프 스윕', 'Deep Half Sweep', array['딥하프 넘기기']::text[], array['딥 하프에서 상대 허벅지를 안고 반대 손으로 발목을 잡는다','엉덩이를 상대 아래로 더 넣는다','상대 다리를 들어 올리며 돌아 옆으로 넘긴다','위로 올라온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/bottom (기 시도 18)', 28),
  ('half-guard', 'waiter-sweep', '웨이터 스윕', 'Waiter Sweep', array['웨이터']::text[], array['딥 하프에서 상대 다리를 양팔로 안아 들어 올린다(쟁반처럼)','발로 상대 반대 무릎을 밀어 벌린다','상대를 머리 위로 넘긴다','위로 올라온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/bottom (기 시도 15)', 29),
  ('half-guard', 'homer-simpson-sweep', '호머 심슨 스윕', 'Homer Simpson Sweep', array['호머심슨']::text[], array['딥 하프에서 상대 다리를 안은 채 머리를 바닥에 댄다','무릎으로 일어서며 상대 다리를 밀어 올린다','상대가 등으로 넘어진다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/bottom (기 시도 14)', 30),
  ('half-guard', 'deep-half-to-x-guard', '딥 하프 → X 가드', 'Deep Half to X-Guard', array['딥하프 X가드']::text[], array['상대가 서면 안은 다리를 어깨에 얹는다','반대 다리로 상대 반대 허벅지를 건다','X 모양 훅','X 가드 스윕']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/bottom (기 시도 10)', 31),
  ('half-guard', 'backstep-from-deep-half', '백스텝 (딥 하프 상대)', 'Backstep from Deep Half', array['딥하프 백스텝']::text[], array['안긴 다리를 뒤로 돌리며 몸을 돌린다','상대 등 뒤로 넘어간다','허리띠를 잡고 훅','백']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/top (기 시도 23)', 32),
  ('half-guard', 'whizzer-from-deep-half', '위저 (딥 하프 상대)', 'Whizzer from Deep Half', array['딥하프 위저']::text[], array['상대 팔을 위에서 감아(위저) 조인다','안긴 다리를 펴며 엉덩이를 낮춘다','상대 어깨를 바닥으로 누른다','다리를 빼 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/top (기 시도 16)', 33),
  ('half-guard', 'knee-slice-from-deep-half', '니슬라이스 (딥 하프 상대)', 'Knee Slice from Deep Half', array['딥하프 니슬라이스']::text[], array['안긴 다리 무릎을 상대 몸 위로 올린다','상대 머리를 눌러 둔다','정강이로 미끄러져 다리를 뺀다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph deep-half-guard/top (기 시도 15)', 34),
  ('half-guard', 'recover-full-guard-from-quarter', '쿼터 가드 → 풀 가드', 'Recover Full Guard from Quarter Guard', array['쿼터 가드 회복']::text[], array['상대 발목만 걸린 쿼터 가드에서 프레임을 만든다','엉덩이를 빼며 무릎을 상대 배 앞으로','다리를 상대 허리 위로 넘긴다','하프나 클로즈드 가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 35),
  ('half-guard', 'knee-shield-from-quarter', '쿼터 가드 → 니 쉴드', 'Knee Shield from Quarter Guard', array['쿼터 니 쉴드']::text[], array['발목 건 채 엉덩이를 뺀다','위 무릎을 상대 배 앞에 세운다','아래 다리로 다시 다리를 감는다','니 쉴드 하프']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 36),
  ('half-guard', 'complete-pass-from-quarter', '쿼터 가드 패스', 'Complete Pass from Quarter', array['쿼터 패스']::text[], array['크로스페이스로 상대 머리를 돌린다','걸린 발목을 반대 발로 밀어 빼낸다','체중을 가슴에 싣는다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 19)', 37),
  ('half-guard', 'knee-through-from-quarter', '쿼터 가드 → 마운트', 'Knee Through from Quarter', array['쿼터 니 스루']::text[], array['크로스페이스로 상대를 눌러 둔다','걸린 발을 빼며 무릎을 상대 배 위로 미끄러뜨린다','반대 다리를 넘긴다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 13)', 38),
  ('half-guard', 'sweep-from-quarter-guard', '쿼터 가드 스윕', 'Sweep from Quarter Guard', array['쿼터 스윕']::text[], array['언더훅을 잡고 옆으로 돈다','걸린 발목을 당겨 상대 중심을 뺏는다','앞으로 밀며 올라온다','사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/bottom (기 시도 10)', 39),
  ('half-guard', 'kimura-from-quarter-guard', '기무라 (쿼터 가드 탑)', 'Kimura from Quarter Guard Top', array['쿼터 기무라']::text[], array['상대가 프레임 짚은 손목을 잡는다','반대 팔을 아래로 넣어 내 손목','상대 어깨를 누른다','팔을 등 뒤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph quarter-guard/top (기 시도 5)', 40),
  ('half-guard', 'half-guard-to-x-guard', '하프가드 → X 가드', 'Half Guard to X-Guard', array['하프 X가드']::text[], array['상대가 서면 감은 다리 아래로 머리를 넣는다','반대 다리로 상대 반대 허벅지를 건다','상대 다리를 어깨에 얹는다','X 가드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom (기 시도 4)', 41),
  ('half-guard', 'back-door-escape-from-half', '백 도어 이스케이프 (하프)', 'Back Door Escape from Half Guard', array['백도어']::text[], array['상대가 패스하며 체중이 앞으로 쏠리면 상대 다리 아래로 몸을 뺀다','상대 엉덩이 뒤로 빠져나온다','터틀이나 등 뒤로','백 테이크']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 42),
  ('half-guard', 'knee-torque-sweep', '니 토크 스윕', 'Knee Torque Sweep', array['무릎 비틀기 스윕']::text[], array['감은 상대 다리를 양 다리로 비틀어 무릎을 바깥으로 돌린다','상대가 균형을 잃으면 언더훅으로 민다','옆으로 넘긴다','마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/bottom (기 시도 1)', 43),
  ('half-guard', 'loop-choke-from-half-top', '루프 초크 (하프 탑)', 'Loop Choke from Half Guard Top', array['하프 루프 초크']::text[], array['상대 깃을 깊게 잡고 상대가 언더훅을 잡으러 머리를 숙이기를 기다린다','깃 잡은 팔로 상대 목을 감듯 돌려 머리를 내 겨드랑이 아래로 넣는다','반대 팔을 상대 등 뒤로 넘겨 바닥을 짚거나 깃을 받쳐 잡는다','몸을 돌려 옆으로 굴러 내려가며 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 44),
  ('half-guard', 'leg-weave-pass', '레그 위브 패스', 'Leg Weave Pass', array['레그 레이스','다리 엮기']::text[], array['한 팔을 상대 위쪽 다리(니 쉴드) 위로 넘겨 아래 다리 밑으로 넣어 바닥을 짚는다(엮기)','머리와 어깨를 낮춰 상대 무릎 두 개를 한데 모은다','스프롤로 엉덩이를 낮추며 감긴 다리를 뺀다','상대 다리를 돌아 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 27)', 45),
  ('half-guard', 'body-lock-pass', '바디락 패스', 'Body Lock Pass', array['보디락 패스']::text[], array['양팔로 상대 허리를 감아 손을 맞잡는다','가슴을 붙이고 엉덩이를 낮춘다','상대 다리를 한쪽으로 몰아 깔아뭉갠다','다리를 빼며 사이드']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 17)', 46),
  ('half-guard', 'crossface-to-combat-base', '크로스페이스 → 컴뱃 베이스', 'Crossface to Combat Base', array['하프 탑 리셋']::text[], array['크로스페이스로 상대를 눌러 둔다','감긴 다리 무릎을 세워 컴뱃 베이스 자세','반대 손으로 상대 무릎을 누른다','니슬라이스로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 17)', 47),
  ('half-guard', 'half-guard-whizzer-counter', '하프 탑 위저 카운터', 'Half Guard Whizzer Counter', array['언더훅 잡혔을 때']::text[], array['상대가 언더훅 잡으면 그 팔을 위에서 감는다','엉덩이를 뒤로 빼 상대가 못 일어나게','팔을 조여 어깨를 바닥으로','오버훅 컨트롤']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 4)', 48),
  ('half-guard', 'half-guard-to-leg-weave', '하프가드 → 레그 위브', 'Half Guard to Leg Weave', array['레그 위브 진입']::text[], array['상대 니 쉴드 다리 위로 팔을 넘긴다','아래 다리 밑으로 손을 넣어 바닥을 짚는다','머리를 낮춰 상대 무릎을 모은다','레그 위브 패스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph half-guard/top (기 시도 3)', 49),
  ('half-guard', 'half-guard-top-control', '하프 탑 기본 자세', 'Half Guard Top Control Basics', array['하프 탑','하프가드 위에서 누르기','하프 탑 컨트롤']::text[], array['감긴 다리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔은 상대 겨드랑이 아래로 넣어 언더훅을 먼저 잡는다','가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 등을 바닥에 눌러 둔다','감긴 다리 발을 반대 발에 걸거나 무릎을 바닥에 붙여 다리를 뺄 준비를 한다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 50),
  ('half-guard', 'half-guard-to-single-leg', '하프가드 → 싱글 레그', 'Half Guard to Single Leg', array['하프 싱글','언더훅 싱글 레그']::text[], array['하프가드에서 언더훅을 잡고 옆으로 돌아 머리를 상대 겨드랑이 아래로 뺀다','무릎으로 일어나며 감았던 상대 다리를 양팔로 안는다','머리를 상대 옆구리에 붙이고 일어선다','안은 다리를 들어 올리며 밀어 넘어뜨리고 위로 올라온다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 51),
  ('half-guard', 'triangle-from-half-guard', '트라이앵글 (하프가드)', 'Triangle from Half Guard', array['하프 트라이앵글','하프가드 삼각 조르기']::text[], array['상대가 크로스페이스를 걸려고 팔을 내 머리 쪽으로 뻗을 때 그 손목을 잡아 밀어낸다','니 쉴드로 거리를 만들고 감은 아래 다리를 빼낸다','밀어낸 팔 쪽 어깨 위로 다리를 넘겨 상대 목 뒤에 걸고 발목을 반대 오금에 잠근다','안에 남은 팔을 반대쪽으로 넘기고 머리를 당기며 조인다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 52),
  ('half-guard', 'coyote-half-guard', '코요테 하프가드', 'Coyote Half Guard', array['코요테 하프','다리 언더훅 하프']::text[], array['하프가드에서 옆으로 돌아 눕고 아래 팔을 상대 감긴 다리 바깥으로 넣어 허벅지를 안는다(다리 언더훅)','위쪽 손으로 상대 반대 발목이나 바지 무릎을 잡는다','안은 다리를 들어 올리며 상대 반대 발목을 당겨 중심을 뺏는다','상대가 뒤로 넘어지면 올라와 사이드나 하프 탑으로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 53),
  ('half-guard', 'deep-half-to-back', '딥 하프 → 백 테이크', 'Deep Half to Back Take', array['딥하프 백','딥 하프 백 잡기']::text[], array['딥 하프에서 상대 허벅지를 안은 채 반대 손으로 허리띠를 잡는다','상대 다리를 들어 올려 상대가 손을 짚고 몸을 돌리게 만든다','허리띠를 당기며 상대 다리 아래에서 등 뒤로 빠져나온다','가슴을 등에 붙이고 훅을 넣어 백 컨트롤로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 54),
  ('half-guard', 'arm-triangle-from-half-top', '암 트라이앵글 (하프 탑)', 'Arm Triangle from Half Guard Top', array['하프 탑 암트라이앵글','가타가타메 하프']::text[], array['하프 탑에서 크로스페이스 대신 상대 머리 아래로 팔을 넣어 목을 감는다','상대 팔을 내 어깨로 밀어 상대 얼굴 옆에 붙이고 양손을 맞잡는다','머리를 바닥 쪽으로 낮추고 가슴으로 어깨를 눌러 상대 팔이 목을 조이게 한다','감긴 다리를 빼지 못하면 그대로 조이고, 빼면 반대쪽으로 돌아 조인다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 55),
  ('passing', 'posture-in-closed-guard', '클로즈드 가드 안에서 자세 잡기', 'Posture inside Closed Guard', array['포스처','가드 안 자세','자세 세우기','포스처 잡기']::text[], array['허리를 펴고 머리를 세워 상대가 당기지 못하게 한다','한 손은 상대 명치를 누르고 반대 손은 허리띠나 골반 옆 바지를 잡아 팔을 편다','팔꿈치를 몸에 붙여 암바 · 기무라에 팔을 내주지 않는다','무릎을 넓게 벌려 베이스를 만든 뒤 가드 열기로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 · BJJGraph closed-guard/top 1위', 1),
  ('passing', 'closed-guard-break-knee', '가드 열기 (무릎 쐐기)', 'Closed Guard Break (Knee Wedge)', array['가드 브레이크','가드 오픈','니 웨지','무릎 넣어 열기']::text[], array['자세를 세운 채 한 무릎을 상대 꼬리뼈 아래에 쐐기처럼 넣는다','뒤로 앉으며 상대 발목 잠금에 압력을 건다','한 손으로 상대 무릎을 눌러 다리를 연다 — 반대 팔은 상대 허벅지를 계속 막는다(두 팔을 동시에 뒤로 빼지 않는다)','열리면 무릎을 다리 사이로 넣어 니슬라이스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''웨지 패스''', 2),
  ('passing', 'standing-guard-break', '스탠딩 가드 브레이크', 'Standing Closed Guard Break', array['서서 가드 열기','스탠딩 가드 오픈','서서 열기']::text[], array['한 손은 상대 깃(또는 가슴)을 잡고 반대 손은 허리띠를 잡아 자세를 세운다','깃 잡은 쪽 발부터 세우고 반대 발도 세워 일어선다','허리를 펴고 허리띠 잡은 손으로 상대 무릎(허벅지 안쪽)을 밀어 내리며 뒤로 한 발 물러난다','다리가 풀리면 한 다리를 내 허벅지 사이에 끼우거나 어깨에 걸어 컨트롤한다','바로 니슬라이스나 토레안도로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §2.5 ''스탠딩 패스''', 3),
  ('passing', 'knee-slice-pass', '니슬라이스 패스', 'Knee Slice Pass', array['니컷','니스루','니 스플릿','knee cut','니 슬라이스','니 슬라이드','knee slice']::text[], array['한 무릎(정강이)을 상대 허벅지 안쪽 위에 올리고 뒷발은 세워 미는 힘을 만든다','같은 쪽 팔로 언더훅(또는 깃)을 잡아 상대 어깨를 바닥에 붙인다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다 — 다리가 다 빠지기 전에 골반을 돌리지 않는다','빠지면 골반을 돌려 가슴을 붙이고 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.2 (안전 규칙) · BJJGraph 거의 모든 가드에서 상위', 4),
  ('passing', 'toreando-pass', '토레안도 패스', 'Toreando Pass', array['불 패스','토레아도','투우사 패스','불파이터 패스','토리안도','toreando','bullfighter pass']::text[], array['양손으로 상대 무릎 뒤 또는 바지 끝을 잡는다','한쪽 무릎을 바닥으로 눌러 ''죽이고'' 반대쪽으로 다리를 밀어 넘긴다','발을 옆으로 옮겨 상대 옆으로 돌아 들어간다','어깨를 가슴에 떨어뜨리고 머리를 컨트롤해 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph open-guard/top 1위', 5),
  ('passing', 'leg-drag', '레그 드래그', 'Leg Drag Pass', array['렉 드래그','다리 끌기','leg drag','레그드래그']::text[], array['상대 한쪽 발목(또는 바지 끝)을 잡는다','그 다리를 내 반대쪽 엉덩이 옆으로 끌어와 허벅지 사이에 끼운다','같은 쪽 무릎을 상대 엉덩이 옆에 붙여 돌지 못하게 막는다','상체를 숙여 가슴을 누르며 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top 3위', 6),
  ('passing', 'double-under-pass', '더블 언더 패스 (스택)', 'Double Under / Stack Pass', array['스택 패스','더블언더','더블 언더훅 패스','스태킹 패스','double under']::text[], array['양팔을 상대 다리 아래로 넣고 손을 모아 허리띠나 깃을 잡는다','상대 엉덩이를 들어 내 허벅지 위에 얹는다(스택)','어깨로 다리를 머리 쪽으로 눌러 공간을 뺏는다','한쪽으로 돌며 다리를 빼내고 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6 · BJJGraph', 7),
  ('passing', 'over-under-pass', '오버 언더 패스', 'Over Under Pass', array['오버언더','오버 언더훅 패스','over under']::text[], array['한 팔은 상대 다리 아래(언더), 반대 팔은 다리 위(오버)로 감는다','머리를 오버 쪽 상대 엉덩이 옆에 붙이고 가슴을 낮춘다','오버 쪽 다리를 내 다리 사이에 끼우고 발끝으로 서서 언더 쪽 다리를 어깨로 든다','다리를 바닥에 눌러 두고 돌아 나와 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.6', 8),
  ('passing', 'long-step-pass', '롱 스텝 패스', 'Long Step Pass', array['롱스텝','롱 스텝','long step']::text[], array['상대 무릎과 반대 어깨(또는 깃)를 잡아 거리를 잡는다','한 다리를 뒤로 길게 뻗으며 엉덩이를 바닥 쪽으로 낮춘다(스프롤)','상대 다리를 바닥으로 눌러 훅이 걸리지 않게 한다','뻗은 다리를 돌려 상대 옆으로 들어가 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 여러 가드 top 공통', 9),
  ('passing', 'half-guard-pass', '하프가드 패스 (크로스페이스 · 언더훅)', 'Half Guard Pass (Crossface & Underhook)', array['하프 패스','크로스페이스 패스','언더훅 패스']::text[], array['언더훅을 먼저 잡고 상대 어깨를 바닥에 눌러 평평하게 만든다','반대 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','내 자유로운 다리로 상대 먼 쪽 다리를 걸어 눌러 가드 회복을 막는다','감긴 다리를 빼내고 가슴을 붙여 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.1 (언더훅 → 눕히기 → 머리 → 먼 다리 → 빼기)', 10),
  ('passing', 'smash-pass', '스매시 패스', 'Smash Pass', array['스매쉬 패스','하프 스매시']::text[], array['하프가드 위에서 상대 니 쉴드 무릎을 바닥으로 누른다','상대 양 무릎이 겹치게 체중으로 눌러 골반을 비튼다','팔꿈치를 바닥에 가깝게 두고 머리로 상대 가슴을 누른다','감긴 다리를 빼며 돌아 사이드 컨트롤로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §4.3 · BJJGraph half-guard/top 2위', 11),
  ('passing', 'butterfly-pass', '버터플라이 패스', 'Butterfly Guard Pass', array['버터플라이 가드 패스','버터플라이 훅 패스','훅 죽이기 패스']::text[], array['양쪽 훅에 똑같이 체중을 싣고 걸어 들어가지 않고 죽일 훅을 한쪽 고른다','한 손으로 상대 그쪽 훅(발)을 바닥으로 밀어 내린다','반대쪽 엉덩이를 뒤로 넓게 빼서 남은 훅이 들지 못하게 한다','하프가드로 내려앉아 니슬라이스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §5.1', 12),
  ('passing', 'combat-base', '컴뱃 베이스', 'Combat Base', array['콤뱃 베이스','한 무릎 세우기','콤뱃베이스','combat base']::text[], array['상대 오픈 가드 앞에서 한 무릎은 바닥, 반대 무릎은 세운다','세운 무릎을 상대 다리 사이에 둔다','허리를 펴고 양손으로 상대 무릎이나 깃을 잡아 거리를 잡는다','상대 반응을 보고 니슬라이스나 헤드쿼터로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 13),
  ('passing', 'knee-slide-from-combat-base', '니 슬라이드 (컴뱃 베이스)', 'Knee Slide from Combat Base', array['컴뱃 베이스 니슬라이스']::text[], array['세운 무릎을 상대 허벅지 안쪽 위로 올려 정강이를 걸친다','같은 쪽 팔로 깃이나 언더훅을 잡아 상대 상체를 누른다','정강이를 바닥까지 미끄러뜨리며 다리를 끝까지 빼낸다','골반을 돌려 가슴을 붙이고 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 22)', 14),
  ('passing', 'pressure-pass', '프레셔 패스', 'Pressure Pass', array['압박 패스']::text[], array['가슴을 상대 가슴에 붙이고 엉덩이를 낮춰 공간을 없앤다','상대 양 다리를 한쪽으로 몰아 무릎과 체중으로 누른다','상대가 힘을 쓰면 버티고 느슨해지면 조금씩 다리를 빼낸다','다리가 빠지면 크로스페이스를 걸어 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 15)', 15),
  ('passing', 'combat-base-to-headquarters', '컴뱃 베이스 → 헤드쿼터', 'Combat Base to Headquarters', array['헤드쿼터 진입']::text[], array['세운 발을 상대 다리 사이에 둔 채 뒷무릎을 들어 일어선다','상대 한 다리를 내 양 허벅지 사이에 끼우고 무릎으로 조인다','반대 손으로 상대 남은 다리 무릎을 바닥으로 눌러 둔다','허리를 펴고 체중을 끼운 다리에 실어 헤드쿼터를 만든다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/top (기 시도 15)', 16),
  ('passing', 'guard-recovery-from-combat-base', '컴뱃 베이스 상대 가드 회복', 'Guard Recovery vs Combat Base', array['컴뱃 베이스 리가드']::text[], array['상대가 세운 무릎을 발바닥으로 밀어 거리를 만든다','엉덩이를 뒤로 빼며(쉬림프) 다리를 상대 허리 높이로 올린다','발을 상대 골반이나 이두에 대어 거리를 지킨다','양발로 거리를 잡았으면 오픈 가드나 클로즈드 가드로 돌아간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/bottom (기 시도 42)', 17),
  ('passing', 'sweep-from-combat-base', '컴뱃 베이스 상대 스윕', 'Sweep vs Combat Base', array['컴뱃 베이스 스윕']::text[], array['상대가 세운 다리의 발목과 반대쪽 소매를 잡는다','발바닥으로 세운 무릎을 밀며 잡은 발목을 내 쪽으로 당긴다','상대가 뒤로 주저앉으면 발목을 놓지 않고 따라 일어난다','상대 다리를 지나 사이드 컨트롤이나 니슬라이스 자세로 올라간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph combat-base/bottom (기 시도 26)', 18),
  ('passing', 'headquarters-position', '헤드쿼터 포지션', 'Headquarters Position', array['HQ','헤드쿼터','헤드쿼터스','headquarters']::text[], array['상대 한 다리를 내 양 허벅지 사이에 끼운다','반대 다리는 손으로 무릎을 눌러 둔다','허리를 펴고 체중을 상대 다리에 싣는다','상대가 미는 쪽을 보고 니컷 · 레그 드래그 · 토레안도 중 하나로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
