  ('passing', 'complete-leg-weave-pass', '레그 위브 패스 마무리', 'Complete Leg Weave Pass', array['레그 위브 완성']::text[], array['머리를 낮춰 상대 양 무릎을 모은 채 다리를 뒤로 뻗는다(스프롤)','엮은 팔로 다리를 계속 누르며 감긴 다리를 빼낸다','다리가 빠지면 상대 머리 쪽으로 돌아 들어간다','크로스페이스를 걸어 사이드 컨트롤로 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph leg-weave/top (기 시도 5)', 45),
  ('passing', 'leg-hook-pass', '레그 훅 패스', 'Leg Hook Pass', array['다리 걸어 패스']::text[], array['내 다리로 상대 한 다리를 걸어 바닥에 눌러 둔다','상체는 크로스페이스나 언더훅으로 고정한다','걸어 둔 다리 너머로 무릎을 넘겨 상대 엉덩이에 붙인다','가슴을 붙여 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 46),
  ('passing', 'shin-shield-recovery', '레그 훅 상대 니 쉴드 회복', 'Shin Shield Recovery', array['레그 훅 디펜스']::text[], array['걸린 다리를 빼며 엉덩이를 뒤로 뺀다','빼낸 다리 무릎을 상대 배 앞에 세워 쉴드를 만든다','아래쪽 다리로 상대 다리를 감는다','니 쉴드 하프가드로 거리를 지킨다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph leg-hook/bottom (기 시도 12)', 47),
  ('passing', 'escape-leg-hook', '레그 훅 빠져나오기', 'Escape Leg Hook', array['레그 훅 이스케이프']::text[], array['걸린 다리 무릎을 상대 쪽으로 돌려 훅을 푼다','엉덩이를 빼며 다리를 빼낸다','빼낸 다리로 상대 다리를 감는다','하프가드를 잡고 언더훅을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph leg-hook/bottom (기 시도 7)', 48),
  ('passing', 'x-pass', 'X 패스', 'X Pass', array['엑스 패스','엑스패스','x pass']::text[], array['상대 한 다리를 손으로 잡아 몸 반대쪽으로 넘긴다','넘긴 다리 위로 무릎을 올려 눌러 둔다','반대 다리 쪽으로 몸을 돌려 지나간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top (기 시도 10)', 49),
  ('passing', 'float-passing', '플로트 패스', 'Float Passing', array['플로팅 패스']::text[], array['상대 다리 위에 체중을 싣지 않고 가볍게 띄워 움직인다','상대 훅 반응을 보며 방향을 바꾼다','빈 쪽으로 빠르게 돌아 들어간다','상대 가슴에 체중을 떨어뜨려 사이드 컨트롤로 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top (기 시도 5)', 50),
  ('passing', 'stand-up-in-closed-guard', '클로즈드 가드 안에서 일어서기', 'Stand Up in Closed Guard', array['가드 안 스탠드업']::text[], array['상대 양 이두나 깃 · 허리띠를 잡는다','한 발을 세우고 반대 발도 세워 일어선다','허리를 펴고 엉덩이를 뒤로 빼 상대가 당기지 못하게 한다','가드가 열리면 바로 패스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/top (기 시도 18)', 51),
  ('passing', 'guard-opening-sequence', '가드 열기 순서', 'Guard Opening Sequence', array['가드 오프닝']::text[], array['자세 세우기 → 무릎 쐐기 → 손으로 무릎 누르기 순으로 간다','안 열리면 서서 열기로 바꾼다','열리는 순간 무릎을 상대 다리 사이로 넣어 다시 닫지 못하게 한다','바로 패스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/top (기 시도 24)', 52),
  ('passing', 'stack-pass-from-closed-guard', '스택 패스 (클로즈드 가드)', 'Stack Pass from Closed Guard', array['가드 스택']::text[], array['가드를 연 뒤 양팔을 상대 다리 아래로 넣는다','상대 엉덩이를 내 허벅지 위로 올린다','어깨로 상대 다리를 머리 쪽으로 눌러 스택한다','한쪽으로 돌아 다리를 빼내고 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 53),
  ('passing', 'knee-slice-from-closed-guard', '니슬라이스 (클로즈드 가드 열고)', 'Knee Slice from Closed Guard', array['가드 열고 니슬라이스']::text[], array['무릎 쐐기로 가드를 연다','열리면 무릎을 상대 허벅지 안쪽 위로 올린다','같은 쪽 팔로 깃이나 언더훅을 잡는다','정강이를 바닥으로 미끄러뜨려 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph closed-guard/top (기 시도 13)', 54),
  ('passing', 'knee-slice-from-seated-guard', '니슬라이스 (시팅 가드 상대)', 'Knee Slice from Seated Guard', array['앉은 가드 니슬라이스']::text[], array['앉은 상대 어깨나 깃을 밀어 눕힌다','무릎을 상대 허벅지 위에 올린다','같은 쪽 팔로 깃이나 언더훅을 잡아 상체를 누른다','정강이를 미끄러뜨려 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 12)', 55),
  ('passing', 'bodylock-pass-from-seated', '바디락 패스 (시팅 가드 상대)', 'Bodylock Pass from Seated', array['앉은 가드 바디락','바디록 패스','바디락']::text[], array['앉은 상대 허리를 양팔로 안는다','가슴을 붙이고 밀어 눕힌다','다리를 한쪽으로 몰아 누른다','다리가 빠지면 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 10)', 56),
  ('passing', 'bull-pass-from-seated', '불파이터 패스 (시팅 가드 상대)', 'Bull Pass from Seated', array['앉은 가드 토레안도','불 패스','불파이터']::text[], array['앉은 상대 양 무릎을 잡는다','밀어 눕히며 한쪽으로 넘긴다','반대로 돌아 들어간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seated-guard/top (기 시도 9)', 57),
  ('passing', 'pass-shin-to-shin-guard', '신 투 신 가드 패스', 'Pass Shin-to-Shin Guard', array['신투신 패스']::text[], array['상대 정강이에 대인 다리를 뒤로 빼거나 바깥으로 돌린다','상대 발목 그립을 끊는다','무릎을 상대 다리 위로 올린다','무릎을 올린 채 니슬라이스로 패스한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph shin-to-shin-guard/top (기 시도 15)', 58),
  ('passing', 'knee-through-vs-shin-to-shin', '니 스루 (신 투 신 상대)', 'Knee Through vs Shin-to-Shin', array['신투신 니스루']::text[], array['정강이에 대인 다리 무릎을 상대 다리 안쪽으로 밀어 넣는다','깃을 잡아 상체를 누른다','무릎을 바닥으로 미끄러뜨린다','다리가 빠지면 사이드 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 59),
  ('passing', 'pass-feet-on-hips-guard', '발 골반 가드 패스', 'Pass Feet on Hips Guard', array['피트온힙스 패스']::text[], array['골반에 댄 상대 발을 손으로 잡아 옆으로 넘긴다','양 무릎을 한쪽으로 모아 눌러 둔다','발을 옮겨 상대 옆으로 돌아 들어간다','가슴을 떨어뜨려 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph feet-on-hips-guard/top (기 시도 4)', 60),
  ('passing', 'counter-sweep', '카운터 스윕 (패스 중)', 'Counter Sweep', array['스윕 되치기']::text[], array['상대가 스윕을 걸면 넘어가는 방향으로 손을 짚는다(포스트)','짚은 쪽으로 체중을 옮겨 버틴다','상대가 밀던 다리를 눌러 힘을 뺀다','상대가 다시 자세를 잡기 전에 바로 패스로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph open-guard/top (기 시도 3)', 61),
  ('passing', 'backstep-pass', '백스텝 패스', 'Backstep Pass', array['백 스텝','힙 스위치 패스','backstep']::text[], array['상대 니 쉴드 무릎을 손으로 눌러 두고 반대 다리를 뒤로 크게 돌려 앉는다','엉덩이를 바닥에 붙이고 상대 다리를 내 다리 사이에 가둔다','상대가 돌아오지 못하게 팔로 허리나 다리를 감는다','다리를 빼내 사이드 컨트롤이나 니 온 밸리로 잇는다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 62),
  ('passing', 'knee-shield-pass', '니 쉴드 패스', 'Knee Shield Pass', array['니실드 패스','무릎 방패 패스','Z가드 패스']::text[], array['상대 니 쉴드 무릎을 손으로 눌러 가슴에서 떼어 낸다','내 가슴을 상대 무릎 위에 붙여 쉴드를 눕힌다','언더훅을 잡아 상대 어깨를 바닥에 붙인다','니슬라이스처럼 정강이로 미끄러져 다리를 빼낸다','크로스페이스를 걸어 사이드 컨트롤로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 63),
  ('passing', 'open-guard-passing-posture', '오픈 가드 패스 자세 · 거리', 'Passing Posture vs Open Guard', array['패스 자세','서서 패스 준비','패싱 포스처']::text[], array['허리를 펴고 무릎을 살짝 굽혀 상대 발이 골반에 닿지 않는 거리에 선다','양손으로 상대 무릎 안쪽이나 바지를 잡아 다리를 컨트롤한다','팔꿈치를 몸에 붙여 소매 그립을 쉽게 내주지 않는다','상대 훅이 걸리면 멈추고 그립을 떼어 낸 뒤 다시 자세를 잡는다','거리가 잡히면 토레안도 · 니슬라이스로 들어간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 64),
  ('passing', 'pass-finish-to-side-control', '패스 마무리 (사이드 안착)', 'Pass Finish to Side Control', array['패스 완성','가슴 붙이기','사이드 안착']::text[], array['다리를 지나는 순간 엉덩이를 낮추고 가슴을 상대 가슴에 붙인다','머리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔로 상대 가까운 팔을 눌러 언더훅과 프레임을 막는다','무릎을 상대 옆구리에 붙여 쉬림프 공간을 없앤다','3초 이상 버틴 뒤 서브미션이나 마운트로 넘어간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 65),
  ('side-control', 'side-control-maintain', '사이드 컨트롤 유지', 'Side Control (Crossface & Underhook)', array['크로스페이스','사이드 잡기','사이드 컨트롤','사이드 유지']::text[], array['무릎을 상대 옆구리에 붙이고 가슴으로 상대 가슴을 누른다','머리 쪽 팔은 상대 목 아래로 넣어 먼 겨드랑이를 잡고 어깨로 턱을 밀어 얼굴을 돌린다(크로스페이스)','반대 팔은 상대 가까운 팔을 옆구리에 눌러 언더훅을 못 잡게 한다','상대가 무릎을 넣으려 하면 골반을 바닥에 떨어뜨려 막는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.1', 1),
  ('side-control', 'side-control-escape', '사이드 이스케이프 (프레임 · 쉬림프)', 'Side Control Escape (Frame & Shrimp)', array['힙 이스케이프','쉬림프','사이드 탈출','사이드 이스케이프']::text[], array['팔뚝 뼈로 상대 목과 골반에 프레임을 만든다','먼저 브릿지로 상대를 띄우고 프레임으로 공간을 지킨다','엉덩이를 빼서(쉬림프) 공간을 만든다 — 한 번에 안 되면 두 번','무릎을 상대와 나 사이로 넣어 가드를 되찾거나 언더훅을 잡고 일어난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.4 · BJJGraph side-control/bottom', 2),
  ('side-control', 'side-to-mount', '사이드에서 마운트 가기', 'Side Control to Mount', array['니 슬라이드 마운트','마운트 전환']::text[], array['크로스페이스로 상대 머리를 반대쪽으로 돌려 둔다','골반 쪽 무릎을 상대 배 위로 미끄러뜨린다','반대 손으로 상대 무릎이나 허벅지를 눌러 다리로 걸지 못하게 한다','무릎이 반대편 바닥에 닿으면 체중을 낮춰 마운트']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.3 · BJJGraph side-control/top 1위', 3),
  ('side-control', 'americana-side', '아메리카나 (사이드)', 'Americana from Side Control', array['키락','아메리카나','키 락','americana']::text[], array['상대 손목을 바닥에 눌러 팔꿈치가 90도로 굽혀지게 한다(손바닥은 위로)','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 손목은 바닥에 붙여 둔다','손목을 바닥에 붙인 채 상대 엉덩이 쪽으로 끌며 팔꿈치를 들어 어깨를 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.4', 4),
  ('side-control', 'kimura-side', '기무라 (사이드)', 'Kimura from Side Control', array['사이드 키무라','키무라','기무라']::text[], array['상대가 내 목을 밀 때 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 머리 쪽으로 돌아 무릎을 상대 머리와 팔 사이에 넣는다','팔꿈치를 몸에 붙인 채 상대 손을 등 뒤로 올려 어깨를 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §11.3', 5),
  ('side-control', 'arm-triangle', '암 트라이앵글 (헤드 앤 암)', 'Arm Triangle (Head and Arm Choke)', array['헤드 앤 암 초크','가타가타메','암트라이앵글','카타가타메']::text[], array['상대 팔을 머리 너머로 넘겨 목과 팔이 함께 잡히게 한다','한 팔을 상대 목 아래로 넣고 반대 손과 맞잡는다(또는 이두를 잡는다)','머리를 상대 팔 바깥쪽에 붙여 팔이 빠지지 않게 한다','반대쪽으로 넘어가 다리를 벌리고 어깨를 눌러 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.8', 6),
  ('side-control', 'darce-choke', '다스 초크', 'D''Arce Choke', array['다스','다르스','다르스 초크','darce']::text[], array['상대가 쉬림프하며 언더훅을 잡으려 할 때 그 팔 아래로 내 팔을 넣는다','넣은 팔을 상대 목 반대편까지 깊게 꿰어 넣는다','반대 팔의 이두를 잡아 8자(피겨 포)를 만들고 상대 머리를 아래로 누른다','먼 쪽 엉덩이로 눕듯 몸을 낮춰 가슴으로 머리와 팔을 함께 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.2 · §9.3', 7),
  ('side-control', 'arm-extraction', '팔 빼내기 (사이드 아래)', 'Arm Extraction from Side Control', array['끼인 팔 빼기']::text[], array['상대가 내 가까운 팔을 끼우면 브릿지로 상대 체중을 띄운다','팔꿈치를 내 몸 쪽으로 당기며 팔을 빼낸다','빼낸 팔로 상대 목이나 골반에 프레임을 만든다','쉬림프로 공간을 만들어 하프나 가드를 되찾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 21)', 8),
  ('side-control', 'elbow-escape-to-guard', '엘보 이스케이프 (사이드)', 'Elbow Escape to Guard', array['팔꿈치 넣어 가드 회복']::text[], array['팔꿈치를 상대 골반에 대어 프레임을 만든다','엉덩이를 빼며(쉬림프) 가까운 무릎을 상대와 나 사이로 넣는다','반대 다리로 상대 다리를 감는다','하프가드로 잡거나 다리를 빼 풀 가드로 돌아간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 20)', 9),
  ('side-control', 'roll-to-turtle', '터틀로 돌기 (사이드)', 'Roll to Turtle', array['사이드에서 터틀']::text[], array['프레임으로 밀며 엉덩이를 빼 공간을 만든다','상대 쪽으로 몸을 돌리며 먼 쪽 무릎을 끌어와 바닥에 댄다','팔꿈치와 무릎을 붙여 터틀을 만들고 목을 지킨다','일어서거나 바로 가드로 돌아간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 12)', 10),
  ('side-control', 'ghost-escape', '고스트 이스케이프', 'Ghost Escape from Side Control', array['고스트']::text[], array['상대가 크로스페이스를 안 걸었을 때 가까운 팔을 상대 몸 아래로 빼고 상대 쪽으로 몸을 돌린다','다리를 상대 머리 쪽으로 돌리며 엉덩이를 뒤로 빼 몸을 빼낸다','무릎을 꿇고 일어나며 상대 등이나 옆구리를 잡는다','상대가 따라오면 터틀 탑이나 백으로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('side-control', 'sit-out-from-side-control', '싯아웃 (사이드)', 'Sit Out from Side Control', array['사이드 싯아웃']::text[], array['언더훅을 잡고 상대 반대쪽으로 엉덩이를 뺀다','무릎으로 일어나며 다리를 상대 뒤로 뺀다','상대 옆이나 뒤로 돌아선다','상대가 엎드리면 터틀 탑을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/bottom (기 시도 5)', 12),
  ('side-control', 'bridge-and-roll-from-side', '브릿지 앤 롤 (사이드)', 'Bridge and Roll from Side Control', array['사이드 업파']::text[], array['양팔로 상대 등이나 허리를 감아 안는다','상대 쪽 발을 당겨 세우고 상대 쪽으로 강하게 브릿지한다','상대가 손을 짚지 못하게 끌어안은 채 굴러 넘긴다','넘어간 뒤 상대 가드 안에서 탑을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 13),
  ('side-control', 'armbar-from-side-control', '암바 (사이드)', 'Armbar from Side Control', array['사이드 암바']::text[], array['상대 먼 쪽 팔을 언더훅으로 잡아 내 가슴에 붙인다','다리를 상대 머리 쪽으로 돌리며 한 다리를 상대 머리 위로 넘긴다','무릎을 모아 팔꿈치를 가두고 상대 엄지가 위를 보게 한다','엉덩이를 들어 팔을 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/top (기 시도 5)', 14),
  ('side-control', 'far-side-armbar', '파 사이드 암바', 'Far Side Armbar', array['먼 쪽 팔 암바']::text[], array['상대 먼 쪽 팔꿈치를 당겨 내 겨드랑이에 가둔다','가까운(머리 쪽) 다리를 상대 머리 위로 넘긴다','앉으며 뒤로 누워 무릎을 모은다','엉덩이를 들어 팔을 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('side-control', 'ezekiel-choke-from-side', '에제키엘 (사이드)', 'Ezekiel Choke from Side Control', array['사이드 에제키엘']::text[], array['한 팔을 상대 머리 아래로 넣는다','넣은 손으로 반대 팔 소매 안쪽을 잡는다','반대 손날을 상대 목 앞에 밀어 넣는다','가슴을 낮추며 양팔을 조여 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 16),
  ('side-control', 'north-south-choke-from-side', '남북 초크 (사이드에서)', 'North-South Choke from Side Control', array['남북 초크','노스사우스','노스사우스 초크']::text[], array['한 팔을 상대 목 아래로 넣으며 남북으로 돈다','어깨를 상대 목에 떨어뜨린다','손을 맞잡고 머리 쪽으로 더 내려간다','체중을 어깨로 실어 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 17),
  ('side-control', 'breadcutter-choke', '브레드커터 초크', 'Breadcutter Choke', array['빵칼 초크','브레드 커터','breadcutter']::text[], array['상대 먼 쪽 깃을 잡는다','팔뚝을 상대 목 앞에 가로로 댄다','무릎을 상대 머리 옆에 붙이고 체중을 싣는다','깃을 당기며 팔뚝으로 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 18),
  ('side-control', 'loop-choke-from-side', '루프 초크 (사이드)', 'Loop Choke from Side Control', array['사이드 루프']::text[], array['상대 깃을 잡고 상대가 나를 향해 돌거나 머리를 들게 만든다','깃 잡은 팔의 팔꿈치를 상대 머리 위로 돌려 목을 감는다','반대 팔을 상대 등 뒤(겨드랑이)로 넣는다','상대 머리 쪽으로 몸을 돌리며 깃을 당겨 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
  ('side-control', 'von-flue-choke', '본 플루 초크', 'Von Flue Choke', array['길로틴 카운터 초크','본플루','von flue']::text[], array['상대가 사이드 아래에서 내 머리를 길로틴으로 잡고 있을 때 어깨를 상대 목에 떨어뜨린다','양손을 맞잡아 상대 어깨 뒤로 감는다','머리를 바닥에 붙이고 가슴으로 상대 어깨와 목을 함께 누른다','체중을 상대 머리 쪽으로 실어 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('side-control', 'triangle-choke-from-side', '트라이앵글 (사이드 위에서)', 'Triangle from Side Control', array['사이드 트라이앵글']::text[], array['상대 먼 팔을 당겨 가두고 가까운 다리를 상대 목 위로 넘긴다','반대 다리를 넘긴 다리 발목 위에 걸어 잠근다','상대 머리를 당기고 무릎을 모은다','허리를 조여 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
  ('side-control', 'belly-down-armbar-from-side', '벨리 다운 암바 (사이드)', 'Belly Down Armbar from Side Control', array['사이드 엎드린 암바']::text[], array['먼 팔을 가둔 채 다리를 상대 머리 위로 넘기며 엎드린다','무릎을 모아 팔을 가슴에 붙인다','엎드린 채 상대 엄지가 위를 보게 손목을 잡는다','엉덩이를 들어 팔을 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 22),
  ('side-control', 'side-control-to-kesa', '사이드 → 곁누르기', 'Side Control to Kesa Gatame', array['사이드 → 케사가타메','케사 전환','케사가타메','스카프 홀드']::text[], array['상대 가까운 팔을 내 겨드랑이에 끼운다','엉덩이를 돌려 앉으며 머리 쪽 팔로 상대 머리를 감는다','다리를 앞뒤로 벌려 베이스를 잡는다','가슴으로 상대 가슴을 눌러 곁누르기를 만든다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 23),
  ('side-control', 'arm-triangle-from-top', '암 트라이앵글 마무리', 'Arm Triangle Finish from Top', array['헤드 앤 암 피니시']::text[], array['상대 팔을 머리 너머로 넘긴 채 목 아래로 팔을 넣는다','손을 맞잡거나 이두를 잡는다','반대쪽으로 넘어가 다리를 벌린다','어깨를 낮춰 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/top (기 시도 2)', 24),
  ('side-control', 'gift-wrap-from-side', '기프트 랩 (사이드)', 'Gift Wrap from Side Control', array['사이드 기프트랩']::text[], array['상대 먼 팔을 당겨 얼굴을 가로지르게 둔다','머리 쪽 팔을 상대 머리 뒤로 넣어 그 손목을 잡는다','반대 손은 상대 팔꿈치를 눌러 팔이 빠지지 않게 한다','테크니컬 마운트나 백으로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('side-control', 'gift-wrap-to-technical-mount', '기프트 랩 → 테크니컬 마운트', 'Gift Wrap to Technical Mount', array['기프트랩 마운트']::text[], array['기프트 랩을 유지한 채 가까운 무릎을 상대 등 뒤로 넣는다','반대 발을 상대 머리 옆에 세운다','가슴으로 상대 어깨를 누른다','테크니컬 마운트를 잡고 백이나 암바로 잇는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph gift-wrap/top (기 시도 13)', 26),
  ('side-control', 'armbar-on-free-arm', '기프트 랩 → 자유 팔 암바', 'Armbar on Free Arm from Gift Wrap', array['기프트랩 암바']::text[], array['기프트 랩으로 한 팔을 가두면 반대 팔이 떠서 쉽게 잡힌다','그 팔을 잡고 다리를 상대 머리 위로 넘긴다','무릎을 모아 팔꿈치를 가둔다','엉덩이를 들어 팔을 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph gift-wrap/top (기 시도 17)', 27),
  ('side-control', 'kimura-from-gift-wrap', '기무라 (기프트 랩)', 'Kimura from Gift Wrap', array['기프트랩 기무라']::text[], array['기프트 랩 손목 그립을 기무라 그립(8자 그립)으로 바꾼다','상대 팔꿈치를 내 몸에 붙인다','상대 손을 등 뒤로 돌린다','어깨가 꺾이면 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph gift-wrap/top (기 시도 5)', 28),
  ('side-control', 'hip-escape-from-gift-wrap', '기프트 랩 빠져나오기', 'Escape Gift Wrap', array['기프트랩 디펜스']::text[], array['가둬진 팔의 팔꿈치를 가슴 쪽으로 당겨 빼낸다','브릿지하며 엉덩이를 뺀다','자유로운 팔로 상대 골반에 프레임을 만든다','무릎을 넣어 가드를 되찾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('side-control', 'side-to-knee-on-belly', '사이드 → 니 온 밸리', 'Side Control to Knee on Belly', array['니온밸리 전환','KOB 전환','니 온 벨리']::text[], array['한 손은 상대 깃, 반대 손은 허리띠나 바지를 잡는다','그립을 당겨 올리며 골반 쪽 무릎을 상대 배 위로 올린다','반대 다리는 펴서 발로 바닥을 밀며 베이스를 잡는다','무릎에 체중을 실어 상대가 돌지 못하게 한다','상대가 밀면 마운트나 다시 사이드로 바꾼다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 30),
  ('north-south', 'north-south', '남북', 'North-South', array['노스 사우스','69 포지션','노스사우스','남북 포지션','남북 컨트롤']::text[], array['사이드에서 머리 쪽 팔을 상대 겨드랑이 아래로, 반대 팔은 상대 골반으로 옮긴다','상대 손이 내 골반을 막으면 그 위로 체중을 떨어뜨려 눌러 둔다','다리를 상대 머리 쪽으로 걸어 돌며 가슴으로 상대 가슴을 누른다','엉덩이를 너무 상대 가슴 위로 올리지 않고 체중을 뒤로 둔 채 기무라 · 초크를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §6.3', 1),
  ('north-south', 'north-south-escape', '남북 이스케이프', 'North-South Escape', array['남북 탈출','노스사우스']::text[], array['양손을 상대 골반에 대어 프레임을 만든다','브릿지하며 몸을 한쪽으로 돌린다','무릎을 상대와 나 사이로 넣는다','하프가드나 가드를 되찾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph north-south/bottom (기 시도 19)', 2),
  ('north-south', 'bridge-and-turn-to-turtle-ns', '남북 → 터틀', 'Bridge and Turn to Turtle from North-South', array['남북 터틀','노스사우스']::text[], array['브릿지로 상대를 띄운다','한쪽으로 몸을 뒤집으며 무릎을 끌어온다','무릎과 팔꿈치를 붙여 터틀을 만든다','일어서거나 가드로 돌아간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 3),
  ('north-south', 'north-south-to-kimura', '남북 기무라', 'North-South to Kimura', array['노스사우스 기무라','남북 키무라']::text[], array['남북에서 상대 팔이 뜨면 그 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','무릎을 상대 머리 옆으로 옮겨 상대가 따라 돌지 못하게 한다','팔꿈치를 몸에 붙이고 상대 손을 등 뒤로 돌려 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph north-south/top (기 시도 19)', 4),
  ('north-south', 'arm-triangle-setup-ns', '암 트라이앵글 세팅 (남북)', 'Arm Triangle Setup from North-South', array['남북 헤드앤암','노스사우스']::text[], array['상대 팔을 머리 너머로 밀어 올린다','팔을 목 아래로 넣고 손을 맞잡는다','사이드로 돌아가며 상대 팔을 가둔다','가슴을 낮춰 어깨로 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 5),
  ('north-south', 'armbar-from-north-south', '암바 (남북)', 'Armbar from North-South', array['남북 암바','노스사우스']::text[], array['상대 팔을 내 가슴에 가둔다','한 다리를 상대 머리 위로 넘기며 앉는다','무릎을 모아 팔꿈치를 가둔다','엉덩이를 들어 팔을 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph north-south/top (기 시도 7)', 6),
  ('north-south', 'americana-from-north-south', '아메리카나 (남북)', 'Americana from North-South', array['남북 키락','노스사우스']::text[], array['상대 손목을 바닥에 누른다','팔 아래로 반대 팔을 넣어 내 손목을 잡는다','어깨를 눌러 상대가 돌지 못하게 고정한다','팔꿈치를 들어 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph north-south/top (기 시도 5)', 7),
  ('knee-on-belly', 'knee-on-belly', '니 온 밸리', 'Knee on Belly', array['니온벨리','무릎 누르기','니온밸리','KOB','니 온 벨리']::text[], array['깃과 바지(또는 허리띠)를 잡는다','가까운 쪽 무릎을 상대 배 위에 올리고 발끝은 바닥에 닿지 않게 한다','반대 다리는 펴서 발로 바닥을 밀며 중심을 잡는다','깃을 위로 당기고 무릎으로 눌러 압박하며 암바 · 초크 · 마운트를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly', 1),
  ('knee-on-belly', 'knee-on-belly-escape', '니 온 밸리 이스케이프', 'Knee on Belly Escape', array['니온벨리 탈출','니온밸리 이스케이프','KOB 이스케이프']::text[], array['상대 무릎을 손으로 치우려 하지 말고 팔뚝으로 무릎과 골반에 프레임을 만든다','상대 쪽으로 돌며 엉덩이를 빼서 무릎을 떨어뜨린다','가까운 무릎을 상대와 나 사이로 넣는다','가드로 돌아오거나 터틀로 돌아 일어난다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly/bottom', 2),
  ('knee-on-belly', 'kob-to-mount', '니 온 밸리 → 마운트', 'KOB to Mount', array['KOB 마운트','니온밸리 마운트 전환']::text[], array['깃을 당기고 반대 손으로 허리띠나 바지를 잡아 상대가 엉덩이를 빼지 못하게 한다','배에 올린 무릎을 상대 반대쪽 옆구리까지 미끄러뜨려 넘긴다','바닥에 디뎠던 다리의 무릎도 바닥에 내려 양 무릎으로 상대 몸통을 조인다','엉덩이를 낮추고 손은 바닥이나 깃을 잡아 마운트를 굳힌다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly/top (기 시도 18)', 3),
  ('knee-on-belly', 'kob-to-side-control', '니 온 밸리 → 사이드', 'KOB to Side Control', array['KOB 사이드','니온밸리 사이드 전환']::text[], array['올린 무릎을 상대 옆구리 쪽 바닥으로 내리며 가슴을 상대 가슴에 붙인다','머리 쪽 팔로 크로스페이스를 걸어 상대 얼굴을 반대쪽으로 돌린다','반대 팔은 상대 먼 팔 아래로 넣어 언더훅을 잡거나 엉덩이를 막는다','무릎을 상대 옆구리와 엉덩이에 붙여 공간을 없앤다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly/top (기 시도 15)', 4),
  ('knee-on-belly', 'far-side-armbar-from-kob', '파 사이드 암바 (니 온 밸리)', 'Far Side Armbar from KOB', array['KOB 암바','KOB 파사이드 암바','스피닝 암바 (니온밸리)']::text[], array['상대가 먼 쪽 팔로 내 무릎을 밀면 그 팔을 양팔로 가슴에 안는다','바닥에 디뎠던 발을 상대 머리 너머로 넘겨 반대쪽에 딛는다','배에 올렸던 무릎은 상대 가슴 위에 그대로 두고 상대 어깨 옆에 엉덩이를 붙여 앉는다','무릎을 모으고 상대 엄지가 위로 오게 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph knee-on-belly/top (기 시도 13)', 5),
  ('knee-on-belly', 'baseball-bat-choke', '베이스볼 배트 초크', 'Baseball Bat Choke', array['야구방망이 초크','베이스볼 초크','야구배트 초크']::text[], array['한 손은 네 손가락을 상대 깃 안쪽에 넣어 깊게 잡고(손바닥이 위) 반대 손은 바로 아래에 엄지를 깃 안에 넣어 야구 방망이 쥐듯 잡는다','손 위치를 바꾸지 않은 채 무릎을 내리며 상대 머리 쪽으로 돈다','남북 자세까지 돌며 가슴을 낮추고 양 팔꿈치를 모은다','팔뚝으로 목을 가위처럼 조여 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 6),
  ('knee-on-belly', 'cross-collar-choke-from-kob', '크로스 칼라 초크 (니 온 밸리)', 'Cross Collar Choke from KOB', array['KOB 크로스 초크','니온밸리 크로스 초크','KOB 초크']::text[], array['니 온 밸리에서 깃을 잡은 손을 상대 깃 안쪽 깊숙이 밀어 넣는다(손바닥 위)','반대 손을 첫 손 아래로 교차해 반대쪽 깃을 깊게 잡는다','무릎으로 배를 계속 누르며 머리를 낮추고 팔꿈치를 몸 쪽으로 당긴다','손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 7),
  ('knee-on-belly', 'armbar-from-kob', '암바 (니 온 밸리, 가까운 팔)', 'Armbar from Knee on Belly', array['KOB 근접 암바','니온밸리 암바','니어 사이드 암바 (니온밸리)']::text[], array['상대가 가까운 쪽 손으로 내 무릎을 밀면 그 팔을 양팔로 안아 가슴에 붙인다','바닥에 디뎠던 발을 상대 머리 너머로 넘겨 반대쪽 귀 옆에 딛는다','엉덩이를 상대 어깨에 바짝 붙여 앉으며 뒤로 눕는다','무릎을 모으고 상대 엄지가 위로 오게 한 뒤 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('knee-on-belly', 'kimura-from-kob', '기무라 (니 온 밸리)', 'Kimura from Knee on Belly', array['KOB 기무라','니온밸리 기무라']::text[], array['상대가 가까운 쪽 손으로 내 무릎을 밀면 그 손목을 잡아 바닥 쪽으로 누른다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','무릎을 상대 옆구리 쪽 바닥에 내리고 가슴으로 어깨를 눌러 고정한다','상대 팔꿈치를 몸에 붙인 채 손을 등 뒤로 돌려 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('knee-on-belly', 'push-knee-and-reguard', '무릎 밀어 가드 회복 (니 온 밸리 아래)', 'Push Knee and Reguard from KOB', array['KOB 리가드','니온밸리 가드 회복']::text[], array['팔꿈치를 몸에 붙이고 팔뚝으로 상대 무릎과 골반에 프레임을 만든다(손바닥으로 밀지 않는다)','상대 쪽으로 몸을 돌리며 엉덩이를 뒤로 빼(쉬림프) 무릎을 떨어뜨린다','가까운 쪽 무릎을 상대 몸 앞으로 넣어 정강이로 막는다','다른 다리도 넣어 하프가드나 오픈 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('knee-on-belly', 'turn-to-turtle-from-kob', '터틀로 돌기 (니 온 밸리 아래)', 'Turn to Turtle from KOB', array['KOB 터틀','니온밸리 터틀']::text[], array['팔꿈치를 붙이고 팔뚝으로 무릎을 막으며 엉덩이를 빼 무릎 압박을 줄인다','상대 쪽으로 몸을 돌려 무릎을 바닥에 대고 엎드린다(터틀)','팔꿈치와 무릎을 붙이고 턱을 당겨 목과 겨드랑이 공간을 막는다','상대 다리를 잡아 싱글 레그로 일어서거나 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('knee-on-belly', 'kob-switch-sides', '니 온 밸리 스위치 (반대쪽으로 옮기기)', 'Knee on Belly Switch', array['니온밸리 스위치','KOB 스위치','무릎 바꾸기']::text[], array['깃과 허리띠(또는 바지)를 잡은 채 상대 배에 올린 무릎에 체중을 싣는다','바닥에 디딘 발로 바닥을 차며 그 다리를 상대 다리 너머 반대쪽으로 넘긴다','배에 있던 무릎을 들어 올리며 넘긴 다리의 무릎을 상대 배에 새로 올린다','반대쪽 니 온 밸리로 자리 잡고 상대가 돌아서면 백이나 암바를 노린다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 12),
  ('knee-on-belly', 'kob-to-back-take', '백 테이크 (니 온 밸리, 상대가 돌아설 때)', 'Back Take from Knee on Belly', array['니온밸리 백 테이크','KOB 백']::text[], array['니 온 밸리 압박에 상대가 나를 등지고 돌아서면 무릎을 내리고 상대 등에 가슴을 붙인다','상대 팔 아래로 팔을 넣어 시트벨트를 잡는다','가까운 쪽 훅부터 상대 허벅지 안쪽에 넣는다','반대 훅을 넣고 상대를 옆으로 눕혀 백 컨트롤을 완성한다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 13),
  ('kesa-gatame', 'kesa-gatame', '곁누르기 (스카프 홀드)', 'Kesa Gatame (Scarf Hold)', array['케사가타메 (스카프 홀드)','스카프 홀드','곁누르기','케사가타메','케사']::text[], array['사이드에서 상대 가까운 팔을 내 겨드랑이에 끼워 잡는다','엉덩이를 상대 옆구리에 붙이고 돌아앉으며 반대 팔로 상대 머리를 감는다','다리를 앞뒤로 넓게 벌려 베이스를 만든다','상대 어깨를 가슴으로 눌러 고정하고 암락이나 마운트 전환을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph side-control/top', 1),
  ('kesa-gatame', 'kimura-from-kesa', '기무라 (곁누르기)', 'Kimura from Kesa Gatame', array['기무라 (케사가타메)','케사 기무라','케사가타메 기무라']::text[], array['겨드랑이에 끼운 상대 팔의 손목을 엉덩이 쪽 손으로 잡는다','머리를 감았던 팔을 풀어 상대 팔 아래로 넣고 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 가슴에 붙이고 체중으로 어깨를 눌러 둔다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 2),
  ('kesa-gatame', 'americana-from-kesa', '아메리카나 (곁누르기)', 'Americana from Kesa Gatame', array['아메리카나 (케사가타메)','케사 키락','케사 아메리카나','다리 아메리카나']::text[], array['겨드랑이에 끼운 상대 팔을 풀어 손목을 잡고 손등이 바닥에 닿게 눌러 팔꿈치를 90도로 만든다','상대 손목 위에 내 다리를 올리고 무릎을 접어 발을 바닥에 두어 손목을 고정한다','머리 감은 팔은 유지한 채 자유로운 손으로 상대 팔꿈치를 잡는다','손목은 바닥에 붙인 채 팔꿈치만 들어 올려 어깨를 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 3),
  ('kesa-gatame', 'arm-triangle-from-kesa', '암 트라이앵글 (곁누르기)', 'Arm Triangle from Kesa Gatame', array['암 트라이앵글 (케사가타메)','케사 헤드앤암','케사 암 트라이앵글','헤드앤암 초크 (곁누르기)']::text[], array['겨드랑이에 끼운 상대 팔을 풀어 상대 머리 너머로 밀어 올려 팔이 자기 목을 가로지르게 한다','머리를 감은 팔을 상대 목 아래로 깊게 넣고 반대 손과 손바닥을 맞잡는다','머리를 상대 어깨에 붙이고 가슴을 낮춰 옆이나 엎드린 자세로 간다','팔꿈치를 모으고 어깨를 낮추며 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 4),
  ('kesa-gatame', 'kesa-to-mount', '곁누르기 → 마운트', 'Kesa Gatame to Mount', array['케사가타메 → 마운트','케사 마운트','케사가타메 마운트 전환']::text[], array['머리를 감은 팔과 겨드랑이에 끼운 팔은 그대로 유지한다','뒤로 접었던 다리(엉덩이 쪽)를 상대 배 위로 넘겨 반대쪽 바닥에 무릎을 댄다','앞으로 뻗었던 다리를 당겨 무릎을 상대 옆구리에 붙인다','엉덩이를 낮추고 양 무릎을 조여 마운트를 굳힌다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 5),
  ('kesa-gatame', 'kesa-to-side-control', '곁누르기 → 사이드', 'Kesa Gatame to Side Control', array['케사가타메 → 사이드','케사 사이드','케사가타메 사이드 전환']::text[], array['머리를 감은 팔과 끼운 팔을 유지한 채 엉덩이를 들어 돌린다','뒤로 접었던 다리의 무릎을 상대 옆구리에 붙이고 가슴을 상대 가슴에 포갠다','머리 감은 팔을 크로스페이스로 바꿔 상대 얼굴을 반대쪽으로 돌린다','끼운 팔은 언더훅으로 바꾸고 무릎과 팔꿈치 사이 공간을 없앤다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 6),
  ('kesa-gatame', 'escape-kesa-gatame', '곁누르기 이스케이프', 'Escape Kesa Gatame', array['케사가타메 이스케이프','케사 탈출','곁누르기 탈출','케사가타메 탈출']::text[], array['끼인 팔의 팔꿈치를 가슴 쪽으로 당기며 손을 내 몸에 붙인다','먼 쪽 손으로 상대 허리띠나 등을 잡고 발을 당겨 세운다','상대 쪽으로 브릿지하며 엉덩이를 빼서 상대와 나 사이에 무릎을 넣는다','하프가드로 돌아오거나 상대 등 뒤로 돌아 백을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph kesa-gatame/bottom (기 시도 8)', 7),
  ('kesa-gatame', 'bridge-escape-from-kesa', '브릿지 이스케이프 (곁누르기)', 'Bridge Escape from Kesa Gatame', array['브릿지 이스케이프 (케사)','케사 브릿지','케사 브릿지 탈출']::text[], array['먼 쪽 팔로 상대 허리띠나 등을 감아 잡고 양발을 엉덩이 가까이 당겨 세운다','끼인 팔의 팔꿈치를 가슴 쪽으로 당겨 상대 팔 조임을 느슨하게 한다','머리 쪽으로 강하게 브릿지하며 상대를 내 몸 너머 반대쪽으로 굴린다','넘어가면 사이드 탑, 상대가 손을 짚어 버티면 그 틈에 엉덩이를 빼 하프가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('kesa-gatame', 'back-take-from-kesa', '백 테이크 (곁누르기 아래)', 'Back Take from Kesa Gatame', array['백 테이크 (케사 아래)','케사 백','케사 백 테이크']::text[], array['먼 쪽 손으로 상대 허리띠나 등 쪽 도복을 잡는다','끼인 팔꿈치를 가슴 쪽으로 당겨 빼며 상대 쪽으로 몸을 돌린다','무릎을 세우고 상대 등 뒤로 돌아 올라가 시트벨트를 잡는다','훅을 넣어 백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('kesa-gatame', 'kuzure-kesa-gatame', '변형 곁누르기', 'Kuzure Kesa Gatame', array['쿠즈레 케사가타메','언더훅 케사','변형곁누르기','모디파이드 스카프 홀드']::text[], array['곁누르기에서 머리를 감는 대신 상대 먼 팔 겨드랑이 아래로 팔을 넣어 언더훅을 잡는다','가까운 팔은 내 겨드랑이에 끼운다','다리를 앞뒤로 벌려 베이스를 잡고 엉덩이를 상대 옆구리에 붙인다','여기서 기무라 · 아메리카나 · 마운트 전환을 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
