  ('kesa-gatame', 'breadcutter-from-kuzure-kesa', '브레드커터 (변형 곁누르기)', 'Breadcutter Choke from Kuzure Kesa', array['브레드커터 (쿠즈레 케사)','쿠즈레 브레드커터','브레드 커터 초크']::text[], array['언더훅 넣은 손으로 상대 뒤쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손은 상대 가까운 쪽 깃을 잡고 팔뚝을 목 앞에 가로로 댄다','엉덩이를 들어 상대 머리 쪽으로 돌며 팔뚝에 체중을 싣는다','뒤 깃을 당기고 팔뚝을 눕히듯 눌러 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 12),
  ('kesa-gatame', 'paper-cutter-choke', '페이퍼 커터 초크', 'Paper Cutter Choke', array['종이칼 초크','페이퍼커터','페이퍼 커터']::text[], array['언더훅 넣은 손으로 상대 목 뒤쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손으로 상대 가까운 쪽 깃을 잡고 팔뚝을 목 앞에 가로로 댄다','뒤 깃을 당겨 상대 머리를 들어 올리며 팔뚝 쪽 팔꿈치를 바닥으로 떨어뜨린다','가슴을 낮춰 체중을 실어 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 13),
  ('kesa-gatame', 'arm-recovery-to-guard-kesa', '팔 빼고 가드 회복 (변형 곁누르기 아래)', 'Arm Recovery to Guard from Kuzure Kesa', array['쿠즈레 케사 상대 팔 빼고 가드','쿠즈레 탈출','쿠즈레 케사 가드 회복']::text[], array['끼인 팔의 팔꿈치를 가슴 쪽으로 당겨 상대 겨드랑이에서 빼낸다','뺀 팔로 상대 목이나 어깨에 프레임을 만든다','상대 반대쪽으로 엉덩이를 빼며(쉬림프) 무릎을 상대 몸 앞에 넣는다','다른 다리도 넣어 하프가드나 오픈 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 14),
  ('kesa-gatame', 'kesa-straight-armlock', '스트레이트 암락 (곁누르기)', 'Straight Armlock from Kesa Gatame', array['곁누르기 암락','케사 암락','곁누르기 팔 꺾기']::text[], array['겨드랑이에 끼운 상대 팔의 손목을 잡고 팔꿈치 안쪽이 위를 보게 돌린다','앞으로 뻗은 다리의 무릎을 세워 허벅지를 상대 팔꿈치 아래에 받친다','머리 감은 팔과 가슴으로 상대 어깨를 눌러 움직이지 못하게 한다','손목을 바닥 쪽으로 눌러 허벅지 위에서 팔꿈치를 편다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 15),
  ('kesa-gatame', 'kesa-leg-hook-escape', '다리로 머리 걸어 빼기 (곁누르기 아래)', 'Leg Over Head Escape from Kesa Gatame', array['케사 다리 걸기 탈출','곁누르기 레그 훅 이스케이프','다리 걸어 뒤로 넘기기']::text[], array['상대 머리가 높이 떠 있을 때 끼인 팔꿈치를 가슴 쪽으로 당겨 둔다','먼 손으로 상대 어깨나 턱을 밀어 머리를 더 뒤로 보낸다','상대 등 뒤에서 가까운 다리를 들어 올려 발이나 정강이로 상대 얼굴을 걸어 뒤로 당긴다','상대가 뒤로 넘어가면 팔을 빼고 일어나 사이드 탑이나 암바로 간다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 16),
  ('kesa-gatame', 'reverse-kesa-gatame', '리버스 곁누르기 (리버스 스카프 홀드)', 'Reverse Kesa Gatame (Reverse Scarf Hold)', array['리버스 케사','우시로 케사가타메','리버스 스카프 홀드','뒤곁누르기']::text[], array['사이드에서 상대 발 쪽을 보고 돌아앉으며 엉덩이를 상대 옆구리에 붙인다','머리 쪽 팔로 상대 가까운 팔을 언더훅해 겨드랑이에 끼운다','반대 손은 상대 먼 쪽 바지나 엉덩이를 잡고 다리를 벌려 베이스를 만든다','엉덩이 쪽 다리를 상대 허리 위로 넘겨 마운트로 가거나 그대로 눌러 둔다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 17),
  ('mount', 'mount-maintain', '마운트 유지', 'Mount Maintenance', array['그레이프바인','마운트 잡기','마운트 컨트롤','로우 마운트']::text[], array['무릎을 상대 겨드랑이 가까이 올리고 엉덩이를 낮춘다','상대가 브릿지하면 그쪽으로 손을 짚어 균형을 잡는다','발을 상대 다리 안쪽으로 감아(그레이프바인) 엉덩이 빼기를 막는다','한 팔로 크로스페이스를 걸어 얼굴을 돌려 두면 상대가 반응해 공격 기회가 생긴다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.1 · BJJGraph mount/top 1위', 1),
  ('mount', 'mount-escape-upa', '마운트 이스케이프 (업파)', 'Mount Escape (Upa / Trap and Roll)', array['업파','브릿지 앤 롤','트랩 앤 롤','업파 이스케이프']::text[], array['상대 한 팔을 양손으로 감싸 가슴에 붙이고 같은 쪽 발을 내 발로 밟아 묶는다(트랩)','양발을 엉덩이 가까이 당겨 세운다','묶은 쪽 어깨 너머로 높게 브릿지하며 몸을 돌린다','굴러 넘겨 상대 클로즈드 가드 안에서 자세를 세운다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom 2위', 2),
  ('mount', 'mount-escape-elbow', '마운트 이스케이프 (엘보)', 'Elbow Escape from Mount', array['니 투 엘보','쉬림프 이스케이프','엘보 이스케이프']::text[], array['마운트 아래에서 팔꿈치로 상대 무릎이나 골반에 프레임을 만든다','한쪽 엉덩이를 빼며(쉬림프) 공간을 만든다','같은 쪽 무릎을 상대 다리 아래로 넣어 빼낸다','반대쪽도 같은 방법으로 빼서 하프가드나 클로즈드 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom 1위', 3),
  ('mount', 'technical-mount', '테크니컬 마운트', 'Technical Mount', array['테크 마운트','테크니컬 마운트 자세']::text[], array['상대가 옆으로 돌면 그쪽 무릎을 상대 등 뒤에 붙인다','반대 다리는 상대 머리 옆에 발을 세워 무릎을 높인다','가슴으로 상대 어깨를 눌러 등이 바닥에서 뜨지 않게 한다','여기서 암바 · 백 테이크 · 초크를 고른다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2 · BJJGraph mount/top', 4),
  ('mount', 'mount-armbar', '마운트 암바', 'Armbar from Mount', array['마운트에서 암바']::text[], array['상대 한 팔을 가슴에 붙여 잡고 반대 손은 바닥을 짚는다','잡은 팔 쪽 무릎을 상대 머리 옆으로 올려 S 자세로 앉는다','반대 다리를 상대 얼굴 위로 넘기며 뒤로 눕는다 — 다리를 펴지 말고 상대를 몸 쪽으로 조인다','무릎을 모으고 엄지가 위로 가게 손목을 잡은 뒤 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2', 5),
  ('mount', 'mount-cross-collar-choke', '크로스 칼라 초크 (마운트)', 'Cross Collar Choke from Mount', array['마운트 크로스 초크','십자 조르기','마운트 칼라 초크']::text[], array['마운트에서 한 손을 상대 깃 깊숙이 넣는다(손바닥 위로)','반대 손을 첫 손 아래로 교차해 반대 깃을 잡는다','상체를 숙여 머리를 상대 머리 옆 바닥 가까이 둔다','팔꿈치를 바닥 쪽으로 벌리며 손목을 비틀어 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 2위)', 6),
  ('mount', 'ezekiel-choke', '에제키엘 초크', 'Ezekiel Choke', array['이지키엘','소매 초크','에제키엘','이제키엘']::text[], array['마운트에서 한 팔을 상대 머리 아래로 넣는다','머리 아래로 넣은 손으로 반대쪽 팔의 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 손의 손날을 상대 목 앞으로 가로질러 넣는다','소매를 당기고 손날을 밀어 넣으며 팔꿈치를 모아 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기)', 7),
  ('mount', 'mount-americana', '아메리카나 (마운트)', 'Americana from Mount', array['마운트 키락','마운트 아메리카나','키락 (마운트)']::text[], array['상대 손목을 바닥에 눌러 팔꿈치가 90도가 되게 한다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','가슴을 낮춰 상대 어깨를 바닥에 고정한다','손목은 바닥에 붙인 채 팔꿈치를 들어 올려 어깨를 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §11.4', 8),
  ('mount', 'gift-wrap', '기프트 랩 → 백 테이크', 'Gift Wrap to Back Control', array['기프트랩','기프트 랩','선물 포장']::text[], array['상대가 옆으로 돌면 상대 위쪽 팔을 얼굴을 가로질러 반대쪽으로 밀어 넘긴다','상대 머리 뒤로 팔을 넣어 그 손목을 잡는다(기프트 랩)','자유로운 손으로 상대 어깨나 골반을 누르며 다리를 상대 등 뒤로 넣는다','그쪽으로 굴러 앉으며 시트벨트를 잡고 훅을 넣어 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §7.2', 9),
  ('mount', 'consolidate-mount', '마운트 굳히기 (하이 마운트)', 'Consolidate Mount', array['하이 마운트','마운트 올리기']::text[], array['상대 팔꿈치를 밀어 올리며 무릎을 겨드랑이까지 걸어 올라간다','엉덩이를 낮추고 발을 상대 몸에 붙인다','손은 바닥을 짚거나 상대 깃을 잡아 균형을 잡는다','여기서 크로스 칼라 초크나 암바를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 시도 21)', 10),
  ('mount', 'bridge-and-roll', '브릿지 앤 롤 (마운트)', 'Bridge and Roll from Mount', array['업파 변형']::text[], array['상대 한 팔을 양손으로 감싸 가슴에 붙이고 같은 쪽 발을 내 발로 묶는다','양발을 엉덩이 가까이 당겨 세운다','묶은 쪽 어깨 너머로 브릿지하며 상대를 굴려 넘긴다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom (기 시도 22)', 11),
  ('mount', 'heel-drag-escape', '힐 드래그 이스케이프', 'Heel Drag Escape', array['뒤꿈치 끌기 탈출','힐 드래그','뒤꿈치 끌기']::text[], array['팔꿈치를 붙여 상대 골반에 프레임을 만들고 한쪽 엉덩이를 살짝 뺀다','같은 쪽 발뒤꿈치로 상대 발목을 안쪽으로 끌어와 내 다리 사이로 넣는다','그 다리 위로 내 무릎을 넘겨 상대 다리를 내 양다리로 감는다(하프가드)','언더훅을 잡거나 니 쉴드를 세워 하프가드를 지킨다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom (기 시도 13)', 12),
  ('mount', 'mount-escape-to-half-guard-back-take', '마운트 탈출 → 하프 → 백 테이크', 'Mount Escape to Half Guard Back Take', array['마운트 탈출 백']::text[], array['엘보 이스케이프로 상대 한쪽 다리를 감아 하프가드를 만든다','상대 겨드랑이 아래로 팔을 넣어 언더훅을 잡고 옆으로 돌아 눕는다','언더훅 쪽으로 몸을 세우며 상대 등 뒤로 돈다','시트벨트를 잡고 훅을 넣어 백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/bottom (기 시도 7)', 13),
  ('mount', 'mount-to-technical-mount', '마운트 → 테크니컬 마운트', 'Mount to Technical Mount', array['테크니컬 마운트 전환']::text[], array['상대가 옆으로 돌면 그쪽(등 쪽) 무릎을 상대 등 뒤에 붙인다','반대 다리는 상대 머리 옆에 발을 세워 무릎을 높인다','가슴으로 상대 어깨를 눌러 상대가 다시 눕지도 엎드리지도 못하게 한다','여기서 암바나 백 테이크를 고른다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 시도 8)', 14),
  ('mount', 'technical-mount-to-back', '테크니컬 마운트 → 백', 'Technical Mount to Back Control', array['테크니컬 마운트 백']::text[], array['테크니컬 마운트에서 시트벨트를 먼저 잡는다','상대 머리 옆에 세웠던 발을 상대 배 앞으로 넘겨 허벅지 안쪽에 훅으로 넣는다','등 뒤에 붙였던 무릎 쪽으로 몸을 눕히며 그 다리도 훅으로 넣는다','가슴을 등에 붙여 백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('mount', 'armbar-from-technical-mount', '암바 (테크니컬 마운트)', 'Armbar from Technical Mount', array['테크니컬 마운트 암바']::text[], array['상대 위쪽 팔을 양팔로 안아 가슴에 붙인다','머리 옆에 세웠던 발을 상대 머리 너머로 넘긴다','엉덩이를 상대 어깨에 붙인 채 뒤로 눕고 무릎을 모은다','상대 엄지가 위로 오게 잡고 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph technical-mount/top (기 시도 14)', 16),
