  ('mount', 'mounted-triangle', '마운티드 트라이앵글', 'Mounted Triangle', array['마운트 트라이앵글','마운트 트라이앵글 초크']::text[], array['하이 마운트에서 상대 한 팔을 안쪽에 두고 그쪽 다리를 상대 목 뒤로 넘긴다','넘긴 발목을 반대 무릎 뒤에 걸어 잠근다','상대 머리를 당기며 앞으로 몸을 낮추거나 뒤로 굴러 가드 트라이앵글로 간다','다리를 조여 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/top (기 시도 6)', 23),
  ('mount', 'escape-mounted-triangle', '마운티드 트라이앵글 이스케이프', 'Escape Mounted Triangle', array['마운트 트라이앵글 탈출']::text[], array['턱을 당기고 갇힌 팔의 팔꿈치를 몸 쪽으로 당겨 목에 공간을 만든다','양손으로 상대 허벅지나 골반을 잡고 머리 쪽으로 강하게 브릿지한다','상대가 앞으로 넘어가 손을 짚으면 다리 걸림이 느슨해진 틈에 머리를 뺀다','엉덩이를 빼며 무릎을 넣어 하프가드나 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 24),
  ('mount', 'mounted-crucifix', '마운티드 크루시픽스', 'Mounted Crucifix', array['마운트 크루시픽스','마운티드 크루시픽스']::text[], array['하이 마운트에서 상대 한 팔을 머리 쪽으로 밀어 올리고 그 팔 위에 무릎을 올려 다리로 가둔다','반대쪽 팔은 내 팔로 감아(오버훅) 겨드랑이에 끼운다','상대 양팔이 벌어진 십자 모양이 되게 체중을 낮춘다','여기서 에제키엘이나 깃 초크 · 암바를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('mount', 'cross-collar-choke-from-high-mount', '크로스 칼라 초크 (하이 마운트)', 'Cross Collar Choke from High Mount', array['하이 마운트 초크']::text[], array['하이 마운트에서 한 손을 상대 깃 안쪽 깊숙이 넣는다(손바닥 위)','반대 손을 첫 손 아래로 교차해 반대쪽 깃을 깊게 잡는다','머리를 상대 머리 옆 바닥 가까이 낮추고 팔꿈치를 몸 쪽으로 당긴다','손목을 안으로 비틀어 양 팔뚝으로 목을 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph high-mount/top (기 시도 15)', 26),
  ('mount', 'arm-triangle-from-mount', '암 트라이앵글 (마운트)', 'Arm Triangle from Mount', array['마운트 헤드앤암','마운트 암 트라이앵글','헤드앤암 초크 (마운트)']::text[], array['상대 한쪽 팔꿈치를 조금씩 밀어 올려 그 팔이 상대 얼굴을 가로지르게 하고 내 머리를 그 손 바깥쪽에 붙인다','상대 머리 뒤로 팔을 둘러 목 아래 깊게 넣고 반대 손과 손바닥을 맞잡는다','갇힌 팔의 어깨 쪽으로 마운트에서 내려와 다리를 넓게 벌려 베이스를 잡는다','머리를 바닥 쪽으로 낮추고 어깨로 상대 팔을 목에 밀어 넣으며 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 27),
  ('mount', 'kimura-from-mount', '기무라 (마운트)', 'Kimura from Mount', array['마운트 기무라']::text[], array['상대가 밀어내는 손목을 잡아 바닥에 누른다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 가슴에 붙이고 반대쪽 발을 상대 머리 옆에 세워 상대가 구르지 못하게 한다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 시도 3)', 28),
  ('mount', 'modified-mount', '모디파이드 마운트', 'Modified Mount', array['변형 마운트']::text[], array['상대가 옆으로 돌면 한 무릎은 상대 등 뒤 반대 무릎은 상대 배 앞 바닥에 붙인다','상대 위쪽 팔을 내 팔이나 겨드랑이로 가둔다','엉덩이를 낮추고 가슴으로 상대 어깨를 눌러 상대가 눕거나 엎드리지 못하게 한다','여기서 깃 초크나 기무라를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 29),
  ('mount', 'cross-collar-choke-from-modified-mount', '크로스 칼라 초크 (모디파이드 마운트)', 'Cross Collar Choke from Modified Mount', array['변형 마운트 초크']::text[], array['옆으로 누운 상대의 위쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손을 교차해 아래쪽 깃을 잡거나 상대 어깨 뒤 도복을 잡는다','몸을 낮추며 팔꿈치를 몸 쪽으로 당긴다','손목을 비틀어 양 팔뚝으로 목을 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/top (기 시도 13)', 30),
  ('mount', 'kimura-from-modified-mount', '기무라 (모디파이드 마운트)', 'Kimura from Modified Mount', array['변형 마운트 기무라']::text[], array['상대 위쪽 팔의 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 내 몸에 붙이고 가슴으로 어깨를 눌러 둔다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/top (기 시도 10)', 31),
  ('mount', 'bridge-escape-from-modified-mount', '모디파이드 마운트 이스케이프', 'Escape Modified Mount', array['변형 마운트 탈출']::text[], array['위쪽 팔의 팔꿈치를 몸에 붙이고 팔뚝으로 상대 골반이나 무릎에 프레임을 만든다','브릿지하며 엉덩이를 빼서 상대 무릎과 내 몸 사이에 공간을 만든다','그 틈으로 아래쪽 무릎을 넣어 상대 다리를 감는다','하프가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph modified-mount/bottom (기 시도 12)', 32),
  ('mount', '3-4-mount', '3/4 마운트', '3-4 Mount', array['쓰리쿼터 마운트','쓰리 쿼터 마운트','3/4 마운트']::text[], array['상대가 내 한쪽 다리를 하프가드처럼 감아도 반대 무릎은 바닥에 붙이고 엉덩이를 낮춰 버틴다','크로스페이스로 상대 얼굴을 걸린 다리 반대쪽으로 돌린다','자유로운 발로 상대 발목을 밀어 내리거나 걸린 다리 무릎을 세워 빼낸다','뺀 다리를 바닥에 내려 풀 마운트를 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 33),
  ('mount', 'elbow-escape-from-3-4-mount', '3/4 마운트 이스케이프', 'Elbow Escape from 3-4 Mount', array['쓰리쿼터 탈출']::text[], array['팔꿈치를 붙이고 팔뚝으로 상대 골반에 프레임을 만든다','걸리지 않은 쪽으로 엉덩이를 빼며(쉬림프) 상대 다리와 내 몸 사이 공간을 만든다','자유로운 무릎을 넣어 니 쉴드를 세우거나 언더훅을 잡는다','하프가드를 굳히거나 가드를 회복한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 3-4-mount/bottom (기 시도 11)', 34),
  ('mount', 'triangle-from-mount', '트라이앵글 (마운트에서)', 'Triangle from Mount', array['마운트 트라이앵글 진입']::text[], array['상대 한 팔을 머리 쪽으로 밀어 올려 내 다리 안쪽에 두고 반대 팔은 바깥에 둔다','안쪽에 둔 팔 쪽 무릎을 상대 머리 옆까지 올린다','그 다리를 상대 목 뒤로 넘겨 발목을 반대 무릎 뒤에 건다','마운티드 트라이앵글에서 조이거나 뒤로 굴러 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 3-4-mount/top (기 시도 7)', 35),
  ('mount', 'reverse-armbar-from-mount', '리버스 암바 (마운트)', 'Reverse Armbar from Mount', array['역 암바','리버스 암바']::text[], array['상대가 내 가슴을 밀면 그 손목을 겨드랑이에 끼워 가둔다','상대 팔꿈치의 뾰족한 부분이 위를 보도록 팔을 비튼다','양손으로 상대 팔꿈치 바로 위를 감싸 잡는다','겨드랑이로 손목을 누르며 팔꿈치를 가슴 쪽으로 당겨 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph mount/top (기 시도 1)', 36),
  ('mount', 'trap-and-roll-from-high-mount', '트랩 앤 롤 (하이 마운트)', 'Trap and Roll from High Mount', array['하이 마운트 업파']::text[], array['팔꿈치를 몸에 붙이고 엉덩이를 발 쪽으로 빼 상대 마운트를 배 아래로 내린다','상대 한 팔을 가슴에 안아 잡고 같은 쪽 발을 내 발로 묶는다','발을 세워 묶은 쪽 어깨 너머로 브릿지해 굴린다','상대 가드 안에서 자세를 세워 탑을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph high-mount/bottom (기 시도 10)', 37),
  ('mount', 'frame-escape-from-high-mount', '하이 마운트 프레임 이스케이프', 'Frame Escape from High Mount', array['하이 마운트 탈출']::text[], array['팔꿈치를 몸에 붙이고 양 팔뚝으로 상대 골반을 밀어 프레임을 만든다','브릿지하며 엉덩이를 발 쪽으로 빼 상대를 배 아래로 내린다','프레임을 유지한 채 쉬림프로 무릎을 상대 다리 안으로 넣는다','하프가드로 돌아오거나 엘보 이스케이프로 이어 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph high-mount/bottom (기 시도 15)', 38),
  ('mount', 'mount-collar-choke-defense', '크로스 칼라 초크 막기 (마운트 아래)', 'Cross Collar Choke Defense under Mount', array['마운트 초크 디펜스','크로스 초크 방어 (마운트 아래)','깃 초크 막기']::text[], array['상대 첫 손이 깃에 들어오면 턱을 당기고 그 손목을 양손으로 잡아 더 깊이 못 들어오게 한다','두 번째 손이 교차해 들어오려 하면 그 팔의 팔꿈치나 손목을 밀어 막는다','상대가 몸을 숙이면 그쪽 팔과 발을 묶고 브릿지한다(업파)','넘기거나 틈이 생기면 엘보 이스케이프로 가드를 회복한다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 39),
  ('back-control', 'back-control-maintain', '백 컨트롤 유지 (시트벨트 · 훅)', 'Back Control (Seatbelt & Hooks)', array['시트벨트','훅 넣기','백 잡기','백 마운트','백 컨트롤']::text[], array['한 팔은 상대 어깨 위, 반대 팔은 겨드랑이 아래로 넣어 손을 맞잡는다(시트벨트) — 어깨 위로 넘긴 조르는 손이 아래, 겨드랑이 아래로 넣은 손이 그 위를 덮어 보호한다','양 발을 상대 허벅지 안쪽에 넣는다(훅) — 아래쪽 훅이 더 중요','언더훅 팔꿈치는 몸에 붙이고 어깨 위 팔은 길게 감는다','상대가 빠지려 하면 위쪽 다리를 상대 골반 위로 넘기고 앉아 올라가 다시 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.2~8.3', 1),
  ('back-control', 'rear-naked-choke', '리어 네이키드 초크', 'Rear Naked Choke', array['RNC','백 초크','리어 네이키드','네이키드 초크','마타레옹']::text[], array['시트벨트와 훅을 유지한 채 상대 손과 싸워 조르는 팔을 턱 아래로 밀어 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 상대 뒤통수에 둔다','가슴을 상대 등에 붙이고 턱을 당긴다','가슴을 펴며 팔꿈치를 모아 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.4 · BJJGraph back-control/top 1위', 2),
  ('back-control', 'bow-and-arrow-choke', '보우 앤 애로우 초크', 'Bow and Arrow Choke', array['활 조르기','보우앤애로우','보우 앤 애로','보우 앤 애로우']::text[], array['백에서 한 팔을 상대 어깨 위로 넘겨 반대쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손으로 깃 잡은 손과 같은 쪽 상대 바지(무릎 쪽)를 잡는다','깃 잡은 쪽 다리를 상대 어깨 위로 넘기며 옆으로 눕는다','깃을 당기고 다리로 밀어 활처럼 당겨 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top (기 3위)', 3),
  ('back-control', 'body-triangle', '바디 트라이앵글', 'Body Triangle', array['보디 트라이앵글']::text[], array['백에서 한 다리를 상대 배 앞으로 가로질러 넣는다','그 발목을 반대 무릎 뒤에 걸어 삼각형으로 잠근다','시트벨트를 유지한 채 상대를 내 쪽으로 눕힌다','상대가 돌지 못하게 조이며 초크를 준비한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top', 4),
  ('back-control', 'back-escape', '백 이스케이프', 'Back Escape', array['백 빠져나오기','핸드 파이팅','백 탈출']::text[], array['턱을 당기고 양손으로 상대 조르는 팔을 잡아 막는다(핸드 파이팅)','상대 언더훅 반대쪽(조르는 팔 쪽)으로 어깨를 바닥에 붙이며 눕는다','엉덩이를 바닥 쪽으로 밀어 훅 하나를 빼낸다','상대 다리를 넘어 돌아서 가드나 사이드 탑으로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §8.3 · BJJGraph back-control/bottom', 5),
  ('back-control', 'hand-fighting-from-back', '핸드 파이팅 (백 아래)', 'Hand Fighting from Back', array['손 싸움','핸드파이팅','백 디펜스']::text[], array['턱을 당기고 어깨를 올려 목 공간을 좁힌다','양손으로 상대 어깨 위로 넘어온 팔(조르는 팔)의 손목을 잡는다','덮고 있는 손이 아니라 그 아래의 조르는 손을 막아야 한다','손목을 아래로 밀어 내리며 조르는 팔 쪽으로 어깨를 바닥에 붙여 탈출로 이어 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/bottom (기 시도 28)', 6),
  ('back-control', 'hip-escape-from-back', '힙 이스케이프 (백 아래)', 'Hip Escape from Back Control', array['백 힙 이스케이프']::text[], array['조르는 팔을 양손으로 막으며 그쪽 어깨를 바닥에 붙인다','엉덩이를 바닥 쪽으로 밀어 내려 아래쪽 훅을 빼낸다','뺀 다리로 상대 다리를 넘어가 엉덩이를 바닥에 붙인다','돌아서 하프가드로 가거나 사이드 탑으로 올라간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 7),
  ('back-control', 'turn-into-opponent', '돌아서 마주 보기 (백 아래)', 'Turn into Opponent from Back', array['백에서 돌아서기']::text[], array['조르는 팔을 막으며 어깨를 바닥에 붙여 훅 하나를 빼낸다','엉덩이를 바닥에 붙이고 상대 쪽으로 몸을 돌려 마주 본다','상대 다리를 내 다리로 감는다','하프가드나 클로즈드 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('back-control', 'shoulder-walk-escape', '숄더 워크 이스케이프', 'Shoulder Walk Escape from Back', array['어깨 걷기']::text[], array['조르는 팔을 양손으로 막고 그쪽 어깨를 바닥에 붙인다','양 어깨를 번갈아 밀며 몸을 상대 다리 쪽(아래)으로 조금씩 미끄러뜨린다','엉덩이가 상대 훅 아래로 빠지면 상대 다리를 넘어간다','돌아서 사이드 탑으로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('back-control', 'rear-naked-choke-setup', '리어 네이키드 초크 세팅', 'Rear Naked Choke Setup', array['RNC 셋업','RNC 세팅']::text[], array['시트벨트에서 덮고 있는 손으로 상대 손을 떼어내 밀어 내린다','조르는 팔의 손날을 상대 턱 아래로 파고들게 하거나 상대 어깨를 밀어 턱을 들게 한다','조르는 팔꿈치가 상대 턱 아래 정중앙에 오게 넣는다','반대 팔 이두를 잡고 뒤통수에 손을 얹어 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top (기 시도 11)', 10),
  ('back-control', 'seat-belt-control', '시트벨트 컨트롤 (훅 없이)', 'Seat Belt Control', array['시트벨트만','시트벨트 백 컨트롤']::text[], array['훅 없이 시트벨트만 잡고 가슴을 상대 등에 붙인다','상대 옆으로 누우며 상대 어깨를 바닥에 붙여 등이 뜨지 않게 한다','상대가 돌아 나오려 하면 시트벨트를 당기며 따라 돈다','틈이 나면 훅을 넣어 풀 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 11),
  ('back-control', 'seat-belt-to-full-back', '시트벨트 → 풀 백 컨트롤', 'Seat Belt to Full Back Control', array['훅 넣기']::text[], array['시트벨트를 잡고 조르는 팔이 위로 오게 상대와 함께 옆으로 눕는다','아래쪽 다리의 훅을 상대 허벅지 안쪽에 먼저 넣는다','위쪽 다리의 훅을 넣는다','가슴을 등에 붙이고 팔꿈치를 모아 백 컨트롤을 굳힌다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 12),
  ('back-control', 'escape-seat-belt-control', '시트벨트 빠져나오기', 'Escape Seat Belt Control', array['시트벨트 탈출']::text[], array['턱을 당기고 양손으로 상대 조르는 팔을 잡아 막는다','조르는 팔 쪽으로 어깨를 바닥에 붙이며 엉덩이를 바닥으로 내린다','상대가 훅을 넣기 전에 상대 다리를 넘어 돌아선다','터틀로 가거나 가드를 회복한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph seat-belt-control-back/bottom (기 시도 12)', 13),
  ('back-control', 'body-triangle-lock', '바디 트라이앵글 잠그기', 'Body Triangle Lock', array['바디 트라이앵글 세팅']::text[], array['백에서 한 다리를 상대 배 앞으로 가로질러 넣는다','그 발목을 반대 다리 무릎 뒤에 걸어 삼각형으로 잠근다','다리를 조여 상대가 엉덩이를 빼지 못하게 한다','시트벨트를 유지하며 초크를 노린다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph gift-wrap/top (기 시도 12)', 14),
  ('back-control', 'rnc-from-body-triangle', '리어 네이키드 초크 (바디 트라이앵글)', 'RNC from Body Triangle', array['바디 트라이앵글 RNC','바디 트라이앵글 리어 네이키드 초크']::text[], array['바디 트라이앵글로 상대를 고정하고 가슴을 등에 붙인다','핸드 파이팅으로 상대 손을 떼어 내고 조르는 팔을 턱 아래로 넣는다','그 손을 반대 팔 이두에 걸고 반대 손은 뒤통수에 둔다','가슴을 펴고 팔꿈치를 모아 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('back-control', 'cross-collar-choke-from-back', '크로스 칼라 초크 (백)', 'Cross Collar Choke from Back', array['백 크로스 초크','슬라이딩 칼라 초크','오쿠리에리지메','백 깃 초크']::text[], array['백에서 한 팔을 상대 어깨 위로 넘겨 반대쪽 깃을 네 손가락을 넣어 깊게 잡는다','반대 손은 상대 겨드랑이 아래로 넣어 반대쪽 깃이나 어깨 도복을 잡아 당겨 깃을 팽팽하게 한다','깃 잡은 쪽으로 몸을 옆으로 눕히며 팔꿈치를 당긴다','깃을 당기고 가슴을 펴며 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 16),
  ('back-control', 'short-choke', '숏 초크', 'Short Choke', array['짧은 초크','쇼트 초크']::text[], array['조르는 팔이 턱 아래로 다 들어가지 않을 때 팔뚝을 턱 아래에 건다','반대 손으로 그 손목을 잡아 맞잡는다','가슴을 펴고 어깨를 뒤로 당기며 팔뚝을 목 쪽으로 끌어당긴다','팔꿈치를 모아 조인다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 17),
  ('back-control', 'body-triangle-escape-to-side', '바디 트라이앵글 빠져나오기', 'Body Triangle Escape', array['바디 트라이앵글 탈출']::text[], array['조르는 팔을 막으며 발목이 걸린 무릎 쪽으로 몸을 돌려 그쪽 어깨를 바닥에 붙인다','손으로 상대 위쪽 무릎을 아래로 눌러 밀며 엉덩이를 뺀다','삼각형이 느슨해지면 상대 다리를 넘어간다','돌아서 사이드 탑으로 올라간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 18),
  ('back-control', 'hip-escape-to-turtle-from-back', '백 → 터틀로 빠지기', 'Hip Escape to Turtle from Back', array['백에서 터틀']::text[], array['조르는 팔을 막으며 엉덩이를 바닥 쪽으로 빼 훅을 느슨하게 한다','몸을 엎어 무릎과 팔꿈치를 바닥에 댄다(터틀)','팔꿈치와 무릎을 붙이고 턱을 당겨 목 공간을 막는다','한 발을 세워 베이스를 잡고 일어서거나 가드로 돌아온다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 19),
  ('back-control', 'armbar-from-back', '암바 (백)', 'Armbar from Back', array['백 암바','리어 암바']::text[], array['상대가 양손으로 내 조르는 팔을 잡고 밀면 그 위쪽 팔을 양팔로 가슴에 안는다','위쪽 다리를 상대 어깨 위로 넘겨 얼굴을 가로지르게 한다','옆으로 떨어져 누우며 아래쪽 다리는 상대 가슴 위로 올려 무릎을 모은다','상대 엄지가 위로 오게 잡고 엉덩이를 들어 팔꿈치를 편다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph back-control/top (기 시도 4)', 20),
  ('back-control', 'rear-triangle', '리어 트라이앵글', 'Rear Triangle Choke', array['백 트라이앵글','리어 트라이앵글 초크']::text[], array['시트벨트에서 상대 한 팔을 언더훅 쪽에 가두고 위쪽 다리를 그 어깨 위로 넘긴다','넘긴 다리의 발목을 손으로 끌어당겨 반대 다리 무릎 뒤에 걸어 삼각형을 만든다','몸을 옆으로 눕히며 상대 머리를 당긴다','다리를 조여 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 21),
  ('back-control', 'kimura-from-back', '기무라 (백)', 'Kimura from Back', array['백 기무라']::text[], array['상대가 내 아래쪽(언더훅) 손을 잡으면 어깨 위로 넘긴 손으로 그 손목을 잡는다','아래쪽 팔을 빼서 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치를 몸에 붙이고 그쪽으로 몸을 옆으로 틀어 눕는다','상대 손을 등 뒤로 돌려 올리며 꺾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph rear-triangle/top (기 시도 8)', 22),
  ('back-control', 'rolling-back-take-reversal', '백 아래에서 되치기', 'Rolling Back Take Reversal', array['백 리버설']::text[], array['조르는 팔을 막고 어깨를 바닥에 붙여 훅 하나를 빼낸다','상대 다리를 넘어가 그 다리를 양팔로 안는다','안은 다리 쪽으로 구르며 상대를 넘긴다','상대 등 뒤로 돌아 올라가 시트벨트를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph body-triangle/bottom (기 시도 5)', 23),
  ('back-control', 'back-to-mount-transition', '백 → 마운트 (상대가 등을 바닥에 붙일 때)', 'Back Control to Mount', array['백에서 마운트','리마운트','백 마운트 전환']::text[], array['상대가 등을 바닥에 붙이며 빠지려 하면 시트벨트를 잡은 채 아래쪽 훅을 빼지 않고 버틴다','상대 등이 바닥에 닿으면 위쪽 다리를 상대 배 위로 넘긴다','뒤에 있던 다리를 빼서 양 무릎을 상대 옆구리에 붙인다','엉덩이를 낮춰 마운트를 굳힌다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 24),
  ('back-control', 'ezekiel-from-back', '에제키엘 초크 (백)', 'Ezekiel Choke from Back', array['백 에제키엘','소매 초크 (백)','이지키엘 (백)']::text[], array['백에서 한 팔을 상대 어깨 위로 넘겨 목을 감는다','그 손으로 반대쪽 팔 소매 안쪽(손목 부분)을 잡는다','소매가 잡힌 손의 손날을 상대 목 앞으로 가로질러 넣는다','가슴을 펴고 소매를 당기며 손날을 밀어 조인다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 25),
  ('turtle', 'turtle-basics', '터틀 (자세 · 방어)', 'Turtle (Basics & Defense)', array['거북이','터틀 자세','터틀','터틀 포지션','거북이 자세']::text[], array['무릎과 팔꿈치를 바닥에 대고 팔꿈치를 무릎에 붙여 틈을 없앤다','턱을 당기고 두 손으로 깃이나 목을 지켜 초크 그립을 막는다','팔을 밖으로 뻗지 않는다(팔이 나가면 크루시픽스에 걸린다)','상대가 한쪽에 붙으면 반대쪽으로 엉덩이를 빼며 다리를 돌려 가드를 되찾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §10.6', 1),
  ('turtle', 'turtle-back-take', '터틀에서 백 테이크', 'Back Take from Turtle', array['터틀 백','거북이에서 백','터틀 백 테이크','백 잡기']::text[], array['상대 옆에서 가슴을 등에 붙이고 손으로 목을 위협해 상대 팔꿈치를 들게 한다','가까운 무릎을 상대 팔꿈치와 무릎 사이에 쐐기처럼 넣는다','반대 손으로 상대 먼 쪽 골반을 당겨 내 쪽으로 붙이고 반대 다리로 상대 다리 뒤를 건다(첫 훅)','상대가 옆으로 넘어가면 나머지 훅을 넣고 시트벨트를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJ Commons §10.5 · BJJGraph turtle/top 1위', 2),
  ('turtle', 'turtle-flatten', '터틀 뒤집기 (사이드로)', 'Turtle Breakdown to Side Control', array['터틀 브레이크다운','터틀 뒤집기','브레이크다운','터틀 플래튼']::text[], array['터틀 옆에서 가까운 팔을 상대 가까운 겨드랑이 아래로 넣어 상대 손목을 잡는다','반대 손은 상대 가까운 무릎 뒤(오금)를 잡는다','손목을 내 쪽으로 당기고 무릎을 뽑아 상대를 내 쪽으로 굴린다','상대 등이 바닥에 닿으면 가슴을 붙여 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top 2위', 3),
  ('turtle', 'clock-choke', '클락 초크', 'Clock Choke', array['시계 초크','클락초크','클럭 초크']::text[], array['터틀 옆에서 가까운 손을 상대 목 아래로 넣어 먼 쪽 깃을 깊게 잡는다(손바닥이 위를 향하게)','반대 손으로 상대 가까운 손목이나 소매를 잡아 팔을 못 쓰게 한다','가슴을 상대 등 위에 싣고 다리를 상대 머리 쪽으로 걸어 돌린다(시계 바늘처럼)','체중으로 눌러 깃이 목을 조이게 한다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 3위)', 4),
  ('turtle', 'sit-out', '싯아웃 (터틀 탈출)', 'Sit Out from Turtle', array['싯 아웃','싯스루','싯아웃','터틀 싯아웃']::text[], array['터틀에서 상대가 옆이나 뒤에 있을 때 가까운 쪽 손으로 상대 손목을 잡는다','반대 다리를 상대 반대편으로 길게 빼며 엉덩이를 바닥에 앉힌다','잡은 손목을 당기며 어깨로 상대 가슴을 밀어 뒤로 돌아간다','상대 뒤나 옆에 서서 백이나 탑 포지션으로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom 1위', 5),
  ('turtle', 'granby-roll', '그랜비 롤 (가드 회복)', 'Granby Roll to Guard', array['그랜비','어깨 구르기','그랜비롤','숄더 롤']::text[], array['터틀에서 상대 반대쪽 어깨를 바닥에 대고 턱을 당긴다','엉덩이를 들어 어깨 위로 둥글게 구른다','구르는 동안 다리를 상대 쪽으로 돌려 상대 몸을 향하게 한다','다리가 상대 앞에 오면 가드(오픈 · 클로즈드)로 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom', 6),
  ('turtle', 'standing-up-in-base', '터틀에서 일어서기', 'Technical Stand-up from Turtle', array['베이스로 일어나기','테크니컬 스탠드업','터틀에서 일어나기']::text[], array['터틀에서 상대 쪽 손은 상대를 막고 반대 손으로 바닥을 짚는다','짚은 손과 반대쪽 발을 앞에 세운다','엉덩이를 들어 뒤로 빼며 짚은 손 쪽 다리를 뒤로 뺀다','두 발로 선 뒤 상대와 마주 보고 거리를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 33)', 7),
  ('turtle', 'turtle-to-guard', '터틀 → 가드 회복', 'Turtle to Guard', array['터틀 리가드','터틀 가드 회복','가드 리커버리']::text[], array['터틀에서 상대 쪽 팔꿈치와 무릎을 붙여 훅이 들어올 틈을 막는다','상대 반대쪽으로 엉덩이를 바닥에 앉힌다','상대 쪽 다리를 돌려 무릎이 상대를 향하게 한다','발을 상대 골반에 올리고 프레임을 세워 오픈 가드를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 15)', 8),
  ('turtle', 'rolling-to-guard', '구르며 가드 회복', 'Rolling to Guard from Turtle', array['터틀 롤','구르기 가드 회복']::text[], array['터틀에서 턱을 당기고 상대 반대쪽 어깨를 바닥에 댄다','엉덩이를 들어 어깨 너머로 구른다','구르면서 다리를 상대 쪽으로 돌린다','발이 상대 앞에 오면 오픈 가드를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 14)', 9),
  ('turtle', 'sit-through-to-guard', '싯 스루 → 가드', 'Sit Through to Guard', array['싯스루','싯 스루 가드']::text[], array['터틀에서 상대 쪽 손으로 상대 손목이나 팔을 잡는다','먼 쪽 다리를 상대 쪽으로 길게 빼며 엉덩이를 바닥에 앉힌다','상대 쪽으로 몸을 돌려 무릎이 상대를 향하게 한다','다리를 상대 앞에 두고 하프 가드나 오픈 가드를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 14)', 10),
  ('turtle', 'peterson-roll', '피터슨 롤', 'Peterson Roll', array['피터슨','피터슨롤']::text[], array['상대가 뒤에서 허리를 감으면 그 손목을 잡아 내 배에 꽉 붙인다','잡은 팔 쪽 어깨를 바닥에 대고 그쪽으로 구른다','구르면서 상대가 내 위를 넘어가 등이 바닥에 닿는다','잡은 팔을 놓지 않은 채 몸을 돌려 사이드 컨트롤 탑을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/bottom (기 시도 10)', 11),
  ('turtle', 'forward-roll-from-turtle', '앞구르기로 빠지기', 'Forward Roll from Turtle', array['터틀 앞구르기','앞구르기 가드 회복']::text[], array['상대가 뒤에 있을 때 턱을 당기고 머리를 숙인다','한쪽 어깨를 바닥에 대고 앞으로 구른다','구르면서 다리를 상대 쪽으로 돌린다','앉은 자세에서 발을 상대 앞에 두고 오픈 가드를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 12),
  ('turtle', 'turtle-to-back-control', '터틀 → 백 컨트롤 (훅 넣기)', 'Turtle to Back Control', array['터틀 백 훅','터틀에서 훅 넣기']::text[], array['터틀 옆에서 가슴을 상대 등에 붙이고 시트벨트를 잡는다(한 팔은 어깨 위, 한 팔은 겨드랑이 아래)','가까운 발을 상대 허벅지 안쪽에 훅으로 넣는다','훅 쪽으로 상대를 당겨 내 쪽으로 눕힌다','반대 발도 훅으로 넣어 백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 23)', 13),
  ('turtle', 'rolling-back-take', '롤링 백 테이크', 'Rolling Back Take', array['구르며 백 잡기','롤링 백']::text[], array['터틀 옆에서 가까운 팔로 상대 먼 쪽 겨드랑이를 언더훅하고 반대 손으로 허리띠나 허리를 잡는다','상대 등 너머로 어깨를 대고 구른다','구르면서 상대를 함께 넘겨 등 뒤에 자리 잡는다','훅을 넣고 시트벨트를 잡아 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 19)', 14),
  ('turtle', 'chair-sit-to-back', '체어 싯 → 백', 'Chair Sit to Back', array['체어싯','체어 싯 백 테이크']::text[], array['터틀 옆에서 시트벨트를 잡고 가까운 발을 상대 허벅지 안쪽에 훅으로 넣는다','의자에 앉듯 상대 옆에 엉덩이를 내리며 상대를 내 허벅지 위로 당긴다','상대가 내 쪽으로 넘어오면 반대 발도 훅으로 넣는다','시트벨트를 유지한 채 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 9)', 15),
  ('turtle', 'crucifix-from-turtle', '크루시픽스 (터틀)', 'Crucifix from Turtle', array['십자가','크루시픽스','크루시픽스 포지션']::text[], array['터틀 옆에서 가까운 무릎을 상대 팔꿈치와 무릎 사이에 넣어 팔을 벌린다','그 팔을 내 두 다리 사이에 끼우고 발을 걸어 가둔다','반대 손으로 상대 먼 쪽 팔(손목이나 팔꿈치)을 잡는다','상대 등 너머로 구르며 상대를 넘겨 내 등이 바닥에 닿게 한다','다리로 한 팔, 손으로 반대 팔을 잡은 채 크루시픽스를 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 11)', 16),
  ('turtle', 'choke-from-crucifix', '초크 (크루시픽스)', 'Choke from Crucifix', array['크루시픽스 초크','크루시픽스 깃 초크']::text[], array['크루시픽스에서 상대 한 팔은 다리로, 다른 팔은 손으로 가둔 상태를 유지한다','자유로운 손을 상대 턱 아래로 넣어 깃(노기는 팔뚝)을 깊게 잡는다','가슴을 펴고 등을 뒤로 눕히며 상대 턱을 올린다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph crucifix/top (기 시도 21)', 17),
  ('turtle', 'armbar-from-crucifix', '암바 (크루시픽스)', 'Armbar from Crucifix', array['크루시픽스 암바','크루시픽스 레그 암바']::text[], array['크루시픽스에서 다리로 가둔 상대 팔의 팔꿈치가 내 허벅지 사이에 오게 한다','무릎을 모아 팔을 꽉 끼운다','다리를 천천히 뻗으며 엉덩이를 밀어 팔꿈치를 편다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph crucifix/top (기 시도 15)', 18),
  ('turtle', 'kimura-from-crucifix', '기무라 (크루시픽스)', 'Kimura from Crucifix', array['크루시픽스 기무라','크루시픽스 암락']::text[], array['크루시픽스에서 손으로 잡고 있던 상대 팔의 손목을 한 손으로 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대 팔꿈치가 90도로 굽은 상태를 유지한다','손목을 상대 등 쪽으로 천천히 돌리며 조인다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph crucifix/top (기 시도 8)', 19),
  ('turtle', 'escape-crucifix', '크루시픽스 빠져나오기', 'Escape Crucifix', array['크루시픽스 탈출','크루시픽스 이스케이프']::text[], array['가둬진 팔의 팔꿈치를 굽혀 몸 쪽으로 당기고 손을 내 몸에 붙인다','상대 쪽으로 몸을 돌리며 가까운 무릎을 바닥에 댄다','다리에 끼인 팔을 아래로 빼며 터틀로 돌아간다','엉덩이를 빼고 다리를 돌려 가드를 되찾는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 20),
  ('turtle', 'darce-from-turtle', '다스 초크 (터틀)', 'Darce from Turtle', array['터틀 다스','다스','다스 초크']::text[], array['터틀 상대 옆에서 상대 가까운 팔 아래로 내 팔을 넣어 목 반대편까지 깊게 꿰어 넣는다','꿰어 넣은 손으로 반대 팔의 이두를 잡고 반대 손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 아래로 누르며 가슴을 상대 어깨에 싣는다','다리를 상대 머리 쪽으로 걸어 돌며 가슴을 조여 마무리한다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 13)', 21),
  ('turtle', 'anaconda-from-turtle', '아나콘다 초크 (터틀)', 'Anaconda from Turtle', array['터틀 아나콘다','아나콘다','아나콘다 초크']::text[], array['터틀 상대 앞에서 한 팔을 상대 목 아래로 넣어 반대쪽 겨드랑이 아래로 뺀다','뺀 손으로 반대 팔의 이두를 잡고 그 손은 상대 등에 올린다(8자 그립)','상대 팔이 갇힌 쪽으로 구르며 상대를 옆으로 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 4)', 22),
  ('turtle', 'guillotine-from-turtle', '길로틴 (터틀)', 'Guillotine from Turtle', array['터틀 길로틴','길로틴 초크','길로틴']::text[], array['터틀 상대 앞에서 상대 머리를 겨드랑이 아래로 당겨 팔로 목을 감는다(턱 아래에 손목이 오게)','반대 손으로 감은 손의 손목을 잡는다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 뒤로 눕는다','다리로 상대 허리를 감고 가슴을 펴며 팔꿈치를 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 6)', 23),
  ('turtle', 'loop-choke-from-turtle', '루프 초크 (터틀)', 'Loop Choke from Turtle', array['터틀 루프','루프 초크','루프초크']::text[], array['터틀 상대 앞에서 한 손으로 상대 깃을 잡는다(네 손가락 안쪽)','상대 머리를 내 겨드랑이 아래로 눌러 넣으며 깃 잡은 팔로 목을 감는다','반대 팔을 상대 겨드랑이 아래로 넣어 머리 뒤를 받친다','깃을 당기며 몸을 옆으로 돌려 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 5)', 24),
  ('turtle', 'kimura-from-turtle', '기무라 (터틀)', 'Kimura from Turtle', array['터틀 기무라','암락','터틀 암락']::text[], array['터틀 상대 옆에서 상대 손목을 한 손으로 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','상대를 옆으로 굴려 등이 바닥에 닿게 한다','팔꿈치를 90도로 유지하며 손을 등 쪽으로 천천히 돌려 조인다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph turtle/top (기 시도 3)', 25),
  ('turtle', 'single-leg-from-turtle', '터틀에서 싱글 레그', 'Single Leg from Turtle', array['터틀 싱글렉','싱글 레그 (터틀)','레슬 업']::text[], array['터틀에서 상대 가까운 다리를 두 팔로 감싸 가슴에 붙인다','머리를 상대 옆구리에 붙이고 한 발을 세운다','다리를 잡은 채 베이스를 잡고 일어선다','상대 다리를 들어 올려 넘어뜨리고 탑 포지션을 잡는다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 26),
  ('turtle', 'clear-hook-from-turtle', '터틀에서 훅 걷어내기', 'Clear the Hook from Turtle', array['훅 빼기','터틀 훅 방어','훅 디펜스']::text[], array['상대가 훅을 넣으면 그쪽 팔꿈치를 무릎에 붙여 두 번째 훅을 막는다','손으로 훅 들어온 발을 잡아 무릎 아래로 밀어 낸다','훅이 빠지면 상대 반대쪽으로 엉덩이를 앉힌다','다리를 돌려 가드를 되찾는다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 27),
  ('front-headlock', 'front-headlock', '프론트 헤드락', 'Front Headlock', array['프론트 헤드록','헤드락','프론트 헤드락 컨트롤']::text[], array['상대 머리가 아래로 내려오면 한 팔로 턱 아래를 감고 반대 손으로 상대 팔꿈치(삼두)를 잡는다','가슴으로 상대 머리를 누르고 상대 이마가 바닥을 보게 한다','엉덩이를 뒤로 빼고 발을 넓게 벌려 상대가 다리를 못 잡게 한다','백 테이크 · 길로틴 · 아나콘다 · 다스로 이어 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 1),
  ('front-headlock', 'front-headlock-to-back', '프론트 헤드락 → 백', 'Front Headlock to Back', array['헤드락 백 테이크','고 비하인드','프론트 헤드락 백']::text[], array['프론트 헤드락에서 상대 팔꿈치를 잡은 손으로 그 팔을 내 쪽으로 당긴다','머리를 누른 채 잡은 팔 쪽으로 돌아 상대 옆으로 간다','상대 등 뒤에서 시트벨트를 잡는다','훅을 넣고 백 컨트롤로 간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph front-headlock/top (기 시도 17)', 2),
  ('front-headlock', 'guillotine-setup', '길로틴 세팅', 'Guillotine Setup', array['길로틴 셋업','길로틴 그립']::text[], array['프론트 헤드락에서 목을 감은 손의 손목이 상대 턱 아래로 오게 더 깊게 넣는다','반대 손으로 그 손목을 잡아 그립을 완성한다','엉덩이를 뒤로 빼며 상대를 당겨 앉히거나 가드로 끌어들인다','팔꿈치를 몸에 붙이고 길로틴 컨트롤을 유지한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph front-headlock/top (기 시도 8)', 3),
  ('front-headlock', 'guillotine-choke-finish', '길로틴 마무리', 'Guillotine Choke Finish', array['길로틴 피니시','길로틴 초크']::text[], array['그립을 잡고 팔꿈치를 몸에 붙인다','뒤로 눕지 말고 목을 감은 팔 쪽으로 몸을 튼다','다리로 상대 허리를 감는다','가슴을 펴고 팔꿈치를 당기며 체중으로 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 4),
  ('front-headlock', 'high-elbow-guillotine', '하이 엘보 길로틴', 'High Elbow Guillotine', array['마르셀로 길로틴','하이엘보 길로틴','마르셀로틴']::text[], array['목을 감은 팔의 손목이 턱 아래에 오게 깊게 넣는다','반대 팔을 상대 어깨 위로 넘겨 팔꿈치를 높게 세우고 두 손을 손목 그립으로 맞잡는다','높게 올린 팔꿈치로 상대 뒤통수를 아래로 누른다','다리로 상대 허리를 감고 목을 감은 팔 쪽으로 몸을 틀어 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 5),
  ('front-headlock', 'arm-in-guillotine', '암 인 길로틴', 'Arm-in Guillotine', array['팔 넣은 길로틴','암인 길로틴','암 인 길로틴 초크']::text[], array['상대 한 팔과 머리를 함께 감아 손목이 턱 아래에 오게 한다','반대 손으로 그 손목을 잡는다','갇힌 팔 쪽으로 몸을 틀어 눕고 다리로 상대 허리를 감는다','가슴을 펴고 팔꿈치를 당기며 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 6),
  ('front-headlock', 'ten-finger-guillotine', '텐 핑거 길로틴', 'Ten Finger Guillotine', array['열 손가락 길로틴','텐핑거 길로틴']::text[], array['목을 감은 손과 반대 손을 열 손가락으로 깍지 끼듯 맞잡는다','팔꿈치를 모아 상대 머리를 내 가슴에 붙인다','손목 날로 상대 턱을 위로 들어 올리며 가슴을 편다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 7),
  ('front-headlock', 'guillotine-defense', '길로틴 방어', 'Guillotine Defense', array['길로틴 디펜스','길로틴 탈출','길로틴 이스케이프']::text[], array['턱을 당기고 두 손으로 상대 손목을 잡아 목에서 떼어 낸다','머리가 끼인 쪽 팔을 상대 어깨 너머로 넘겨 등을 감싼다','그 어깨로 상대 턱 아래를 누르며 허리를 세운다','같은 쪽으로 돌아 상대 옆으로 빠져 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph front-headlock/bottom (기 시도 17)', 8),
  ('front-headlock', 'guard-recovery-from-guillotine', '길로틴에서 가드 회복', 'Guard Recovery from Guillotine', array['길로틴 탈출','길로틴에서 리가드']::text[], array['턱을 당기고 두 손으로 상대 손목을 잡아 아래로 당긴다','엉덩이를 뒤로 빼며 머리를 겨드랑이에서 뽑아낸다','앉으며 다리를 상대 앞에 둔다','오픈 가드나 버터플라이 가드를 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('front-headlock', 'anaconda-choke', '아나콘다 초크', 'Anaconda Choke', array['아나콘다','아나콘다초크','게이터 롤']::text[], array['프론트 헤드락에서 팔을 상대 목 아래로 넣어 반대쪽 겨드랑이 아래로 뺀다','뺀 손으로 반대 팔의 이두를 잡고 그 손은 상대 등에 올린다(8자 그립)','갇힌 팔 쪽으로 구르며(게이터 롤) 상대를 옆으로 넘긴다','무릎으로 상대 쪽으로 걸어 들어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph front-headlock/top (기 시도 19)', 10),
  ('front-headlock', 'anaconda-to-side-control', '아나콘다 안 되면 사이드', 'Anaconda to Side Control', array['아나콘다 실패 시','아나콘다 포기하고 사이드']::text[], array['아나콘다가 안 조이면 억지로 조이지 말고 그립을 푼다','자유로운 손으로 상대 삼두(팔꿈치)를 잡고 머리를 눌러 무릎으로 일어난다','머리를 누른 채 상대 옆으로 돌아간다','사이드 컨트롤이나 남북으로 자리 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph anaconda-control/top (기 시도 23)', 11),
  ('front-headlock', 'frame-and-posture-from-anaconda', '아나콘다 방어', 'Defend Anaconda', array['아나콘다 디펜스','아나콘다 탈출']::text[], array['턱을 당기고 갇힌 팔의 팔꿈치를 몸에 붙여 조일 공간을 없앤다','자유로운 손으로 상대 골반을 밀어 프레임을 세운다','뒤로 빼지 말고 상대 쪽으로 걸어 들어가며 허리를 세운다','상대가 구르려 하면 같은 방향으로 따라 돌아 머리를 뽑아낸다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph anaconda-control/bottom (기 시도 20)', 12),
