  ('front-headlock', 'japanese-necktie', '재패니즈 넥타이', 'Japanese Necktie', array['일본식 넥타이','재패니즈 넥타이 초크']::text[], array['다스처럼 상대 팔 아래로 팔을 넣어 목까지 꿰고 반대 팔의 이두를 잡는다','그립을 잡은 채 상대 옆으로 눕는다','위쪽 다리를 상대 등 위로 넘겨 허리를 누른다','몸을 둥글게 말며 머리를 아래로 당겨 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 24),
  ('front-headlock', 'darce-from-sprawl', '스프롤 후 다스 초크', 'Darce from Sprawl', array['스프롤 다스','다스 (스프롤)','태클 방어 다스']::text[], array['상대가 태클을 들어오면 스프롤로 다리를 뒤로 빼고 가슴으로 상대 등을 누른다','상대 팔 아래로 내 팔을 넣어 목 반대편까지 깊게 꿰어 넣는다','꿰어 넣은 손으로 반대 팔의 이두를 잡고 그 손은 상대 머리 뒤에 둔다(8자 그립)','상대 머리를 누르며 엉덩이를 내리고 머리 쪽으로 걸어가며 가슴을 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 25),
  ('front-headlock', 'peek-out-escape', '피크 아웃 (프론트 헤드락 탈출)', 'Peek-out Escape from Front Headlock', array['피크아웃','헤드락 피크 아웃','머리 빼기']::text[], array['상대가 머리를 감으면 두 손으로 상대 손목을 잡아 목에서 떼어 낸다','턱을 당기고 얼굴을 상대 팔꿈치가 열린 쪽으로 돌린다','같은 쪽 어깨를 밀어 넣으며 머리를 겨드랑이 밖으로 뽑아낸다','상대 옆이나 뒤로 돌아가 자리를 잡는다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 26),
  ('submission-control', 'armbar-finish', '암바 마무리', 'Armbar Finish', array['암바 피니시','암바','주지 가타메']::text[], array['상대 팔을 가슴에 붙이고 엄지가 위(천장)로 가게 손목을 잡는다','무릎을 모아 팔꿈치를 가둔다','뒤꿈치를 당겨 상대를 내 몸 쪽으로 조인다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 1),
  ('submission-control', 'belly-down-armbar', '벨리 다운 암바', 'Belly Down Armbar', array['엎드린 암바','벨리다운 암바']::text[], array['암바 자세에서 상대가 돌며 방어하면 팔을 놓지 않고 같이 돌아 엎드린다','무릎을 모은 채 상대 팔을 가슴에 붙인다','머리를 들고 엉덩이를 천천히 밀어 팔꿈치를 편다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 2),
  ('submission-control', 'armbar-defense', '암바 방어 (팔 빼기)', 'Armbar Defense', array['암바 디펜스','팔 빼기','암바 이스케이프']::text[], array['손을 맞잡거나 내 팔을 감싸 팔꿈치를 굽힌다','상대 다리 위로 체중을 실어 일어난다(스택)','팔꿈치를 돌려 상대 다리 사이로 빼낸다','가드 안으로 돌아간다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph armbar-control/bottom (기 시도 15)', 3),
  ('submission-control', 'hitchhiker-escape', '히치하이커 이스케이프', 'Hitchhiker Escape', array['엄지 돌려 빼기','히치하이커']::text[], array['암바 걸린 팔의 엄지를 상대 다리 쪽(아래)으로 돌린다','엄지 방향으로 몸을 돌리며 상대 다리 쪽으로 구른다','팔꿈치가 상대 골반에서 벗어나면 팔을 빼낸다','위로 올라와 탑 포지션을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 4),
  ('submission-control', 'back-take-from-armbar', '암바 안 되면 백 테이크', 'Back Take from Armbar', array['암바 백','암바에서 백 테이크']::text[], array['상대가 팔을 빼며 내 쪽으로 돌면 다리를 풀고 상대 등 뒤로 돈다','허리띠나 시트벨트를 잡는다','훅을 넣는다','백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph armbar-control/top (기 시도 13)', 5),
  ('submission-control', 'triangle-from-armbar', '암바 → 트라이앵글', 'Triangle from Armbar', array['암바 트라이앵글','암바에서 트라이앵글']::text[], array['암바가 안 펴지면 상대 머리 위에 있던 다리를 상대 목 뒤로 돌린다','반대 다리로 그 발목 위에 무릎을 걸어 삼각형을 만든다','상대 머리를 당기고 각도를 만든다','무릎을 모으며 조인다','천천히 조이고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph armbar-control/top (기 시도 9)', 6),
  ('submission-control', 'kimura-from-armbar-control', '암바 → 기무라', 'Kimura from Armbar Control', array['암바 기무라','암락']::text[], array['상대가 손을 맞잡아 방어하면 위쪽 손목을 잡는다','반대 팔을 상대 팔 아래로 넣어 내 손목을 잡는다(8자 그립)','앉아 올라오며 상대 팔을 등 쪽으로 돌린다','천천히 돌리고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph armbar-control/top (기 시도 10)', 7),
  ('submission-control', 'omoplata-from-armbar', '암바 → 오모플라타', 'Omoplata from Armbar Control', array['암바 오모플라타','암바에서 오모플라타']::text[], array['암바가 막히면 상대 머리 위에 있던 다리를 상대 어깨 뒤로 돌려 팔을 감는다','상대 쪽으로 앉아 올라온다','손으로 상대 허리를 잡아 앞구르기를 막는다','엉덩이를 앞으로 밀며 천천히 어깨를 꺾는다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 8),
  ('submission-control', 'kimura-trap', '기무라 트랩', 'Kimura Trap', array['기무라 컨트롤','기무라 트랩 시스템']::text[], array['기무라 그립을 잡으면 바로 꺾지 말고 그립을 유지한다','상대가 돌거나 짚는 방향에 따라 스윕 · 백 · 암바로 바꾼다','팔꿈치를 몸에 붙여 그립을 지킨다','기회가 오면 기무라로 마무리한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 9),
  ('submission-control', 'kimura-finish', '기무라 마무리', 'Kimura Finish', array['기무라 피니시','기무라','암락']::text[], array['8자 그립에서 상대 팔꿈치가 90도로 굽은 상태를 유지한다','상대 팔꿈치를 내 몸에 붙이고 상대 어깨가 바닥에서 뜨지 않게 누른다','손목을 상대 등 뒤 머리 쪽으로 천천히 돌린다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 10),
  ('submission-control', 'kimura-to-back-take', '기무라 → 백 테이크', 'Kimura to Back Take', array['기무라 백','기무라 트랩 백 테이크']::text[], array['기무라 그립으로 상대 팔을 등 뒤로 돌려 손을 등에 붙인다','상대가 팔을 지키려 돌면 그 팔을 가둔 채 등 뒤로 돌아간다','훅을 넣는다','백 컨트롤을 완성한다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph kimura-trap/top (기 시도 21)', 11),
  ('submission-control', 'rolling-kimura', '롤링 기무라', 'Rolling Kimura', array['구르는 기무라','롤링 키무라']::text[], array['기무라 그립을 잡고 상대 쪽으로 구른다','구르면서 상대도 함께 넘어가게 한다','그립을 놓지 않고 위로 올라온다','기무라로 마무리하거나 백으로 간다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph kimura-trap/bottom (기 시도 9)', 12),
  ('submission-control', 'kimura-defense', '기무라 방어', 'Kimura Defense', array['기무라 디펜스','기무라 이스케이프']::text[], array['잡힌 팔의 손으로 내 허리띠나 다리를 잡는다','팔꿈치를 몸에 붙이고 상대 쪽으로 돈다','상대 그립 방향으로 굴러 압력을 뺀다','팔을 빼낸다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph kimura-trap/bottom (기 시도 5)', 13),
  ('submission-control', 'kimura-counter-via-roll', '기무라 되치기 (구르기)', 'Kimura Counter via Roll', array['기무라 롤 카운터','기무라 구르기 탈출']::text[], array['상대가 기무라를 걸면 잡힌 팔 쪽으로 먼저 구른다(어깨가 돌아가는 방향)','구르면서 상대를 함께 넘긴다','팔꿈치를 몸에 붙인 채 위로 올라온다','가드 안이나 탑 포지션을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph kimura-trap/bottom (기 시도 4)', 14),
  ('submission-control', 'omoplata-finish', '오모플라타 마무리', 'Omoplata Finish', array['오모플라타 피니시','오모플라타']::text[], array['상대 어깨를 다리로 누른 채 손으로 상대 허리를 잡아 앞구르기를 막는다','상대 골반을 바닥에 눕히고 엉덩이를 상대에게서 멀리 뺀다','앉아 올라오며 엉덩이를 앞으로 민다','천천히 어깨를 꺾고 탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 15),
  ('submission-control', 'omoplata-to-sweep', '오모플라타 → 스윕', 'Omoplata to Sweep', array['오모플라타 넘기기','오모플라타 스윕']::text[], array['상대가 꺾이지 않으면 다리로 어깨를 계속 누른다','상대 반대쪽으로 몸을 돌려 상대를 민다','상대가 넘어가면 위로 올라온다','마운트나 사이드 컨트롤을 잡는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph omoplata-control/top (기 시도 22)', 16),
