  ('submission-control', 'triangle-escape-posture', '트라이앵글 탈출 (자세 세우기)', 'Triangle Escape (Posture Up)', array['트라이앵글 디펜스','트라이앵글 탈출','포스처 업']::text[], array['갇힌 팔꿈치를 내 쪽으로 당기고 허리를 세운다','머리를 들고 상대 다리를 아래로 민다','갇힌 팔 쪽으로 몸을 틀어 각도를 깬다','다리를 풀고 가드 안으로']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph 이름 목록', 25),
  ('submission-control', 'stack-escape-from-triangle', '트라이앵글 스택 탈출', 'Stack Escape from Triangle', array['트라이앵글 스택','스택 이스케이프']::text[], array['갇힌 팔꿈치를 몸에 붙이고 반대 손으로 상대 허벅지를 짚으며 일어선다','상대 엉덩이를 들어 올려 체중을 상대 머리 쪽으로 싣는다(스택)','갇힌 팔을 돌려 다리 사이에서 빼낸다','하프 가드 탑이나 사이드 컨트롤로 간다','스택할 때 상대 목을 과하게 누르지 않는다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph triangle-control/top (기 시도 15)', 26),
  ('submission-control', 'inverted-triangle', '인버티드 트라이앵글', 'Inverted Triangle', array['거꾸로 트라이앵글','인버티드 트라이앵글 초크']::text[], array['상대가 스택하며 머리가 옆으로 빠지면 다리를 풀어 반대 방향으로 다시 감는다','상대 머리와 한 팔을 다리로 다시 가둔다','발목 위에 반대 무릎을 걸어 삼각형을 만든다','무릎을 모으며 천천히 조인다','탭하면 바로 푼다']::text[], true, 'AI 초안(우리 말로 작성) · 참고: BJJGraph triangle-escape-position/bottom (기 시도 10)', 27),
  ('submission-control', 'armbar-grip-break', '암바 그립 풀기', 'Armbar Grip Break', array['암바 그립 브레이크','암바 손 풀기','그립 브레이크']::text[], array['상대가 손을 맞잡아 버티면 무릎을 모은 채 상대 손목을 두 손으로 잡는다','엉덩이를 상대 머리 쪽으로 들며 발로 상대 등이나 엉덩이를 밀어 당기는 힘을 키운다','맞잡은 손이 벌어지면 바로 팔을 가슴에 붙이고 엄지가 위로 가게 한다','엉덩이를 천천히 들어 팔꿈치를 편다','탭하면 바로 푼다']::text[], true, 'AI 2차 검토 추가(우리 말로 작성)', 28)
) as t(position_slug, slug, name_ko, name_en, aliases, steps, is_reviewed, source, sort_order)
join public.positions p on p.slug = t.position_slug
on conflict (slug) do update set
  position_id = excluded.position_id,
  name_ko     = excluded.name_ko,
  name_en     = excluded.name_en,
  aliases     = excluded.aliases,
  steps       = excluded.steps,
  is_reviewed = excluded.is_reviewed,
  source      = excluded.source,
  sort_order  = excluded.sort_order;
